  var DATA = [[0,"2ky7uq","Любовь ⇌ Отвержение"],[2,"od4n3l","Любовь"],[3,"4ot4v1","Любим прежде любых результатов. Достаточно просто быть рядом. (1 Ин. 4:18)"],[4,"14cfemg","Отвержение"],[5,"w7yu3g","Ценность скачет вместе с настроением в комнате. Одобрение проверяется без конца. (Притч. 29:25)"],[6,"1rrz6lw","Асир"],[7,"1q6e0hy","Хозяин"],[9,"139q4pa","«Пища Асира будет изобильна; он будет поставлять лакомства, достойные царя». — Быт. 49:20"],[10,"1phn85e","Принятие"],[11,"14vp5j5","Поклонение"],[12,"rban0x","Эмпатия"],[13,"ialuz7","Забота"],[14,"131gftb","Миротворец"],[15,"1hz63h1","Гостеприимство"],[16,"1pnrzs8","Угодничество"],[17,"1erklrz","Обжорство"],[18,"17gnfud","Онемение чувств"],[19,"1hz63h1","Гостеприимство"],[20,"1a0e585","Атмосфера"],[21,"h4uisp","Питать других"],[22,"7kc3qj","Анна-пророчица"],[23,"1021vn2","Марфа из Вифании"],[24,"1973tfg","Авигея"],[25,"qbd0p7","Варнава"],[26,"k5tvt0","Лидия"],[27,"ijdynt","Авдий"],[28,"1va2xh6","Мария из Вифании"],[30,"1raedx","Создан собирать, кормить и держать пространство для стада. Опасность в том, чтобы пасти чужие чувства вместо душ."],[31,"19tzgt3","В рабстве у комнаты: твоя ценность измеряется тем, все ли сыты, довольны и рады тебе. Служение как способ выжить."],[32,"1skbxvx","Бог убирает зрителей. Ты учишься сидеть в Его присутствии, когда некому служить и некого утешать, и обнаруживаешь, что тебя всё равно любят."],[33,"1pnssuf","Анна в храме (Лк. 2:36–38, из колена Асира): десятилетия поклонения и гостеприимства, которые текут из полноты, а не из страха. Хозяин Присутствия, а не заложник комнаты."],[34,"e2ib2u","Атака приходит, когда кто-то в комнате явно недоволен. Отвержение бьёт сильнее всего посреди твоего лучшего служения (кухня Марфы, Лк. 10:40)."],[35,"yvufpt","Прорыв выглядит так: ты позволяешь кому-то остаться расстроенным из-за тебя и обнаруживаешь, что Божье присутствие не уходит вместе с чужим одобрением. «Лучшее» выбирают, а не зарабатывают."],[36,"1tq8tjm","Брат Лоуренс"],[37,"1lsd5j2","XVII в."],[38,"1tdsods","Монастырский повар, который превратил мытьё посуды в непрерывное общение с Богом («Практика присутствия Божьего»): служение из полноты, а не ради одобрения."],[39,"9hx2j0","Мать Тереза"],[40,"syhnso","XX в."],[41,"6iwya6","Десятилетиями служила умирающим в Калькутте сквозь долгую внутреннюю тьму, держась за Божье присутствие, а не за аплодисменты."],[42,"hw9hk8","Хроническое угодничество, которое заканчивается скрытым, глубоко укоренившимся выгоранием."],[43,"171hvd5","Еда, лента соцсетей или любое отвлечение, чтобы заглушить неловкость в общении."],[44,"o8jng2","Чувство ответственности за эмоциональное состояние всех вокруг."],[45,"1iiexdb","Уход от необходимых конфликтов, из-за чего токсичность растёт без помех."],[46,"12ke28p","Паника, когда кто-то в комнате явно на тебя расстроен."],[47,"wx41ga","Постоянные извинения за то, в чём ты не виноват."],[48,"78277m","Ты остаёшься в односторонних или изматывающих отношениях только ради того, чтобы не испытать боль покинутости."],[49,"wiabx1","Питательная атмосфера, которую хозяин сам создаёт для других, а не требует для себя как топлива."],[50,"j3ibkd","Отвержение / Комфорт"],[51,"11mhj28","Превращает гармонию в оружие: требует жертвовать правдой ради искусственного мира."],[52,"8tomuq","Служитель"],[53,"1ot9pjc","Сирота (утрата веры)"],[54,"7amme0","Одобрение и комфорт"],[55,"1ghmbxv","Отвержение/Комфорт"],[56,"19oxfye","«Раз всего не хватает, я должен утешать себя сам или угождать людям»."],[57,"7mdfjs","<strong>Путь священника:</strong> выстроить твёрдые эмоциональные границы; найти свою идентичность и ценность только в Божьем присутствии; разрушить алтарь принятия и стать настоящим хозяином для Духа."],[58,"1ptd0jr","Выгорание от эмпатии: тяжёлое истощение от того, что ты переживаешь и регулируешь эмоциональную погоду всей организации."],[59,"1y89jyb","Уход в полное молчание и бесконечную ленту, лишь бы больше не принимать чужих нужд и жалоб."],[60,"122nnzh","Жажда одобрения: потребление близости, похвалы и искусственной приятности, чтобы заполнить глубокую пустоту на месте одобрения. (Гал. 1:10)"],[61,"c9ksdw","Чистое поклонение и гостеприимство: создавать атмосферу благодати, не нуждаясь в одобрении."],[62,"anlkp","Всепоглощающая тревога под видом «заботы»; глубокая, почти телесная паника покинутости, если в комнате не все довольны."],[63,"19nw7yf","Задевает сиротскую рану: ощущение, что ты в опасности, пока не зарабатываешь своё место служением и умиротворением."],[64,"1ok73mh","Искусственный и недолгий мир комнаты без конфликтов."],[65,"1ceg3cr","Ком в горле; внезапное, непреодолимое желание задобрить или извиниться, когда кто-то хмурится."],[66,"1c4ylko","Трение с Симеоном (Клинок): его прямолинейная правда разбивает тщательно выстроенный искусственный мир Асира."],[67,"ibgduy","Сразу выйди из комнаты. Выпей холодной воды. Не исправляй чужое настроение. Пусть человек побудет расстроенным."],[68,"19j8ti3","Понять, что «искусственный мир» на самом деле форма контроля и трусости, а не настоящая любовь."],[69,"3ishz","Решение «дать неловкой тишине повисеть»: не заполнять паузы в разговоре извинениями или едой."],[70,"ix8cp","Разрушить алтарь принятия (управление чужими эмоциями) и построить алтарь чистого поклонения (радоваться Божьему присутствию, ничего ни для кого не производя)."],[71,"1021vn2","Марфа из Вифании"],[72,"15j8gz4","Лк. 10:41"],[73,"1q6e0hy","Хозяин"],[74,"11ddagb","Служащий лидер"],[75,"1hz63h1","Гостеприимство"],[76,"494s59","Усердие"],[77,"1eklb0k","Служение"],[78,"1p8ud91","Тревога о результате"],[79,"1iz6o8e","Обида"],[80,"10fbl8e","Контроль"],[81,"zbwlqv","Взяла на себя огромные хлопоты, которых никто не поручал, чтобы заслужить любовь и обеспечить себе место в комнате. Лихорадочно служит и копит глубокую обиду на Марию за то, что та не разделяет её тревогу."],[82,"m4we2c","Иисус прямо называет телесный корень: «Марфа, Марфа… ты тревожишься и заботишься о многом». Алтарь принятия разрушен, и Марфа выбирает «лучшее»: присутствие вместо приятности."],[83,"17lmftg","Заступничество Авигеи"],[84,"v1vy75","1 Цар. 25:23"],[85,"131gftb","Миротворец"],[86,"c5at9i","Заступница"],[87,"mj15l5","Проницательность"],[88,"1utcrn2","Смирение"],[89,"ud1tnz","Быстрота"],[90,"a8laxt","Замужем за глупцом"],[91,"1rh4p5c","Принимает гнев на себя"],[92,"1ln4iyg","Останавливает гнев Давида, которого никто не поручал, вызванный крайней глупостью её мужа. Добровольно берёт вину на себя, чтобы погасить конфликт и спасти свой дом."],[93,"1rgrzj0","Давид благословляет её благоразумие и останавливает кровопролитие. Бог сам разбирается с Навалом, и она переходит из дома глупости в царский дворец."],[94,"1va2xh6","Мария из Вифании"],[95,"cps3t8","Ин. 12:3"],[96,"1nmvlm","Поклоняющаяся"],[97,"172dp0","Преданная ученица"],[98,"1qs7q1e","Щедрость без меры"],[99,"1m3e00c","Присутствие"],[100,"1nhgoaa","Сосредоточенность"],[101,"b8pk0h","Непонятая"],[102,"1yk78h8","Осуждена окружающими"],[103,"w5kmp3","Разбивает алебастровый сосуд и «тратит» годовой заработок на чистое присутствие. Полностью пренебрегает светскими расчётами и денежной критикой мужчин в комнате."],[104,"1ny32q6","Иисус увековечивает её поступок, горячо защищает её от «практичности» Иуды и подтверждает, что чистое поклонение бесконечно ценнее искусственной пользы."],[105,"obqmvt","Мир ⇌ Тревога"],[107,"1w52mwe","Мир (шалом)"],[108,"1h1vrym","Доверие завету. Покой получают, а не зарабатывают. (Ис. 26:3)"],[109,"1gx6saz","Тревога"],[110,"utsz8k","Фильтр угроз перегрет. Парализующее беспокойство, пока не держишь исход под контролем. (Флп. 4:6)"],[111,"15sm38z","Гад"],[112,"58z9az","Воитель"],[114,"1lu9f6i","«Гада будут грабить грабители, но он будет грабить их по пятам». — Быт. 49:19"],[115,"10fbl8e","Контроль"],[116,"1wyj3mi","Защита"],[117,"p4cj7a","Упорство"],[118,"1r435yi","Защитник"],[119,"4q6l2t","Стратег"],[120,"1ja3v0z","Выносливость"],[121,"d6fyf5","Трудоголизм"],[122,"1i4wmn0","Выгорание"],[123,"10fbl8e","Контроль"],[124,"117sk06","Выносливость"],[125,"161ateg","Восстановление"],[126,"1wyj3mi","Защита"],[127,"k0kelb","Воины-гадиты Давида"],[128,"hdfuby","Илия"],[129,"1gzyd1u","Моисей"],[130,"1lvnfs","Неемия"],[131,"1j7zzv7","Иисус Навин"],[132,"1g5wszo","Халев"],[133,"ctda6r","Давид (в бою)"],[134,"mg5djx","Иеффай"],[136,"eiz1ld","Послан занимать и удерживать землю, которую другие бросили. Опасность в том, чтобы удерживать её в одиночку."],[137,"1fzzhmw","В рабстве у аврала: твоя идентичность срослась с ролью того, кто держит стену. Отдых ощущается как предательство всех, кто на тебя рассчитывает."],[138,"d000mi","Бог позволяет тебе рухнуть под кустом. Сон, хлеб и открытие, что дело живёт и без тебя: Он никогда не зависел от твоего адреналина."],[139,"1gi3lfd","Руководить из покоя: стена построена за 52 дня тысячей рук, а не одной. «Гада будут грабить грабители, но он будет грабить их по пятам»."],[140,"e7qjxk","Атака приходит сразу после победы на вершине: угроза Иезавели настигла Илию наутро после Кармила (3 Цар. 19:2), когда адреналин схлынул."],[141,"1tpfv8k","Прорыв выглядит так: ты поручаешь другим то, что может провалиться, и соблюдаешь субботу, пока это происходит. Доверие доказывается тем, что ты отпускаешь, а не тем, что несёшь."],[142,"4wa5n1","Хадсон Тейлор"],[143,"liiwl4","XIX в."],[144,"mlwsgh","Довёл себя до срыва, создавая Китайскую внутреннюю миссию, а потом открыл «обменянную жизнь»: старание сменилось пребыванием во Христе, и дело умножилось."],[145,"1qoqz0l","Эми Кармайкл"],[146,"syhnso","XX в."],[147,"1ja2pgg","55 лет без отпуска боролась в Индии за детей, ставших жертвами торговли людьми; два последних десятилетия, прикованная к постели, написала книги, которые пережили сами спасения."],[148,"1x4b9bc","Ты не поручаешь задачи другим, а потом злишься, что тебе никто не помогает."],[149,"15t9opn","Суббота и выходные кажутся непродуктивными, вызывают тревогу или чувство вины."],[150,"8wqfc9","Ты неосознанно создаёшь или затягиваешь кризисы, чтобы чувствовать себя нужным и незаменимым."],[151,"1vra0k3","Тяжёлое физическое выгорание под видом «упорства»."],[152,"qnfjce","Не можешь уснуть, потому что мысленно решаешь завтрашние проблемы."],[153,"ggvnz","Телесные проявления стресса (мигрени, проблемы с желудком), которые ты игнорируешь, чтобы давить дальше."],[154,"o15ozb","Ритмичная, нерушимая суббота, встроенная в саму битву."],[155,"onnku1","Левиафан / Контроль"],[156,"eo7uke","Внушает ложное чувство ответственности и раздавливает человека исходами, которые ему никогда не предназначалось нести."],[157,"iqoavn","Руководитель"],[158,"1uax87q","Сирота (предательство)"],[159,"10fbl8e","Контроль"],[160,"ssql2f","Левиафан/Контроль"],[161,"190oefu","«Отдых значит развал и подвести людей»."],[162,"1jbokro","<strong>Путь царя или царицы:</strong> руководить из состояния покоя; учиться давать силу и поручать другим, а не нести всё бремя самому; сознательно разобрать алтарь контроля."],[163,"r0rxq5","Адреналиновое выгорание: физический срыв от постоянной сверхбдительности и привычки всё делать в одиночку."],[164,"lvsimb","Изоляция мученика: втайне уверен, что больше никто не справится, и строишь вокруг своей работы непроницаемую стену."],[165,"mbcek4","Контроль: ненасытное желание микроменеджмента, чтобы гарантировать безопасность всей системы. (Иак. 4:13–15)"],[166,"16gokns","Защита по завету: выстоять ради миссии, не присваивая контроль и не обижаясь на других."],[167,"17gzbpk","Тлеющая, приглушённая ярость оттого, что никто не работает так же много и никому не так же важно; под ней прячется глубокое истощение."],[168,"1thbhki","Сиротская рана предательства: подсознательная уверенность «Если я не удержу стены, все погибнут, и никто мне не поможет»."],[169,"12g76os","Пьянящее «моральное превосходство» единственного, кто проливает кровь за дело."],[170,"yfbl14","Сжатые челюсти; поверхностное грудное дыхание; скачущие мысли в отведённое для отдыха время."],[171,"rz1z6q","Трение с Иссахаром (Мудрец): его медленный анализ кажется трусливым бездействием посреди кризиса."],[172,"r15s6d","Отложи телефон. Поставь таймер на 5 минут. Смотри в стену и усилием выравнивай дыхание: по 4 секунды."],[173,"1jza5yn","Признать, что привычка забирать всю ответственность себе на самом деле коренится в гордости и глубоком недоверии Божьему владычеству."],[174,"1flma5k","Ввести жёсткую, нерушимую 24-часовую субботу: ни одного письма, ни одного «пожара»."],[175,"isdxld","Разобрать алтарь контроля и построить алтарь доверия: системно позволять подчинённым ошибаться, учиться и нести вес."],[176,"16p5gnw","Илия на горе Хорив"],[177,"pq0l4","3 Цар. 19:4"],[178,"12foxhd","Пророк"],[179,"58z9az","Воитель"],[180,"1g4c6mu","Ревность"],[181,"1048362","Верность"],[182,"lp6xf8","Мужество"],[183,"1cxz3h","Сверхбдительность"],[184,"1ck9ag2","Изоляция"],[185,"1cje0f1","Синдром мученика"],[186,"11u82o9","Несёт в одиночку весь духовный груз народа, и всё достигает пика на Кармиле. Бежит от угрозы Иезавели в полное одиночество и просит смерти, потому что «остался лишь я один»."],[187,"vnvyxo","Бог обходит богословие стороной и лечит тело: сон, испечённая лепёшка и вода. Затем поручение помазать Азаила, Ииуя и Елисея (3 Цар. 19:15–16): оставшаяся работа разделена и передана другим, а не удержана, и откровение о семи тысячах, которые не преклонили колен."],[188,"jwe5bx","Моисей ударяет по скале"],[189,"1oxg040","Чис. 20:10"],[190,"1nghopl","Избавитель"],[191,"iq4pqo","Законодатель"],[192,"1t4eoif","Кротость"],[193,"1048362","Верность"],[194,"c5at9i","Заступник"],[195,"1ql1gvu","Перегружен"],[196,"1eq9pq7","Раздражение"],[197,"1cyq3y8","Реактивность"],[198,"1023ruj","Несёт эмоциональное истощение от руководства мятежным народом, пока оно не прорывает его границы. Берёт тяжесть чуда на себя: «неужели мы должны дать вам воду из этой скалы?»"],[199,"2vnjb1","Вода течёт, но Бог тут же выносит Моисею приговор за то, что тот не явил Его святость перед народом. Моисей принимает последствия и без горечи полностью передаёт руководство Иисусу Навину."],[200,"1xmnb5m","Неемия на стене"],[201,"1nl4vw2","Неем. 4:17"],[202,"tn5ckg","Строитель"],[203,"1t2qwkr","Правитель"],[204,"1ja3v0z","Выносливость"],[205,"4q6l2t","Стратег"],[206,"1nhgoaa","Сосредоточенность"],[207,"13bh8ln","Переработка"],[208,"1c9dbut","Постоянный стресс"],[209,"qr1xpx","Восстанавливает стену под непрерывным психологическим и физическим давлением. Выдерживает изнурение: в одной руке мастерок для стройки, в другой меч для защиты."],[210,"17z9u4f","Заканчивает стену за 52 дня не одной своей силой, а тем, что выстраивает людей защищать семьи друг друга, и глубоко доверяет: «Наш Бог будет сражаться за нас!»"],[211,"9toupk","Рувим"],[212,"1frm0sx","Первенец"],[214,"8cpu12","«Непостоянный, как вода, ты больше не будешь первым…» — Быт. 49:4"],[215,"1qtsj3","Потакание себе"],[216,"jc64nd","Распорядительность"],[217,"1497stf","Первопроходец"],[218,"1avpcxx","Визионер"],[219,"rkh2c5","Харизма"],[220,"1h03eve","Первым на помощь"],[221,"wrhua5","Похоть"],[222,"birlaa","Импульсивность"],[223,"eckkui","Саботаж себя"],[224,"121iqvp","Потенциал"],[225,"1497stf","Первопроходство"],[226,"1hy3rfy","Лидерство"],[227,"9toupk","Рувим"],[228,"97rxo7","Исав"],[229,"g6ymkc","Блудный сын"],[230,"1maov9s","Давид (тёмная сторона)"],[231,"132deir","Пётр (ранний)"],[232,"1ijoqo5","Царь Саул (ранний)"],[233,"1xj631","Иоанн Марк"],[235,"spmh9a","Первым врывается в дверь с заразительным огнём. Опасность в огне, который сжигает собственный дом."],[236,"17eb68o","В рабстве у желаний: на любое давление есть запасной выход: похлёбка, роман на стороне, внезапный уход. Потенциал постоянно обменивается на облегчение."],[237,"13snfa","Бог ставит рамки, которых ты никогда не выбирал: в дальней стране кончаются деньги, приходят последствия, и голод наконец учит тому, чему не научило потакание себе."],[238,"269ik9","Энергия первенца под управлением: первопроходство с доведением до конца, послужной список завершённых дел. Перстень и одежда возвращены: сыновство, которым распоряжаются, а не которое проматывают."],[239,"1h3wpki","Атака приходит в точке максимального давления и минимальной подотчётности: ты один, устал и в одном клике от облегчения (Быт. 25:29, обессилевший с поля)."],[240,"k1h8bu","Прорыв выглядит так: ты выдерживаешь скучную середину и не бросаешь, и обнаруживаешь, что наследство лежит по ту сторону рутины, от которой ты всё время сбегаешь."],[241,"157l7vz","Августин Блаженный"],[242,"8f8nqs","IV в."],[243,"1rcwy2p","«Дай мне целомудрие… но только не сейчас». Два десятилетия во власти желаний, затем сад в Милане: порыв отдан Богу, и ум, сформировавший целое тысячелетие, стал свободен."],[244,"1scjmvf","Джон Ньютон"],[245,"u4uh1x","XVIII в."],[246,"1nfoymq","Работорговец, сам называвший себя негодяем; благодать нашла его в шторм, и пятьдесят лет он превращал жажду наживы в «Amazing Grace»."],[247,"cdwhy5","Сильный старт в проектах и саботаж прямо перед финишем."],[248,"1n4ea8m","Обмен долгосрочного духовного и профессионального наследства на краткие порции дофамина."],[249,"hqqple","Трудно оставаться с внутренним дискомфортом и не искать сразу выход."],[250,"o2vyot","Хаотичные жизненные повороты под действием неуправляемых эмоциональных порывов."],[251,"w6dumy","Циклы зависимости, которые нужны прежде всего, чтобы заглушить огромное давление собственного потенциала."],[252,"mo7vk8","Резюме, полное потрясающих стартов и внезапных, необъяснимых уходов."],[253,"pbgkr1","Структура и подотчётность, которых ты не выбирал."],[254,"qk2xnt","Велиар / Похоть"],[255,"7q3076","Замыкает выносливость накоротко, создавая непреодолимые сиюминутные желания. Меняет первородство на дофамин."],[256,"1n898co","Ободряющий"],[257,"lcaxef","Сирота (покинутость)"],[258,"1cnn1eb","Комфорт"],[259,"dmz6w3","Велиар/Похоть"],[260,"1o27g0t","«Мой порыв важнее моего первородства»."],[261,"1xchk8t","<strong>Путь царя:</strong> выстроить святые эмоциональные границы и строгую сдержанность в поступках; откладывать немедленное удовольствие, чтобы войти в настоящее, долгое наследство для поколений."],[262,"107wli4","Дофаминовый откат: тяжёлая апатия после рискованных, импульсивных решений или потребления."],[263,"mb1erf","Прятки из стыда после публичного провала в характере, дисциплине или владении эмоциями."],[264,"os3sf4","Аппетит: потребление ощущений (еда, секс, покупки), чтобы обойти трение терпения. (Флп. 3:19)"],[265,"5hygdk","Первопроходство и распорядительность: вести с долгим видением и верно управлять своими желаниями."],[266,"qw6pof","Лихорадочная, удушающая тяга к немедленному облегчению или ощущению; отчаянная потребность почувствовать себя «живым» прямо сейчас."],[267,"m454pe","Сиротская рана покинутости: биологическая интенсивность, которой заглушают чувство глубокой неполноценности или отвержения."],[268,"qjx2gz","Мгновенное неврологическое облегчение от давления ожиданий целых поколений."],[269,"19jmwjl","Внезапная, сильная физическая тяга, которая выдаёт себя за «срочную необходимость» или «заслуженную награду»."],[270,"1gqf0c6","Трение с Иосифом (Бык): бунт против строгих, бесстрастных административных структур Иосифа."],[271,"qx06t1","Сразу напиши человеку, которому ты подотчётен. Перейди в людное место, где тебя хорошо видно."],[272,"1i3lpel","Понять, что выдерживать скуку и рутину и есть настоящий механизм того величия, о котором ты мечтаешь."],[273,"1o21pxc","Максимально затруднить любой доступ к дофамину (например, жёсткие цифровые ограничители, никаких поздних ночей без присмотра)."],[274,"fmicsd","Заменить алтарь потакания себе алтарём распорядительности: научиться ценить наследство поколений выше сиюминутного эмоционального всплеска."],[275,"1m5n7ik","Похлёбка Исава"],[276,"aacpq9","Быт. 25:32"],[277,"1frm0sx","Первенец"],[278,"evz7q4","Добытчик"],[279,"3sm2ze","Сила"],[280,"9oot37","Искусный охотник"],[281,"8dpv4l","Импульсивность"],[282,"14hlq2w","Близорукость"],[283,"1prk9ok","Во власти аппетита"],[284,"56s4md","Огромный, незаработанный потенциал первенца без эмоциональной основы, чтобы им распорядиться. Меняет преимущество для поколений на мгновенное телесное облегчение, потому что «я умираю от голода»."],[285,"tmvjal","Навсегда теряет главное лидерское место. Позже находит некоторую меру мира, подчинившись рамкам и границам, которых не выбирал сам: учится управлять аппетитом и прощает Иакова."],[286,"g6ymkc","Блудный сын"],[287,"1bkc5fu","Лк. 15:13"],[288,"iis1sr","Сын"],[289,"1f8l43x","Наследник"],[290,"j9uidy","Смелость"],[291,"4ylaqp","Честность (на дне)"],[292,"96kic0","Отзывчив на любовь"],[293,"8dpv4l","Импульсивность"],[294,"1c99zuw","Расточительность"],[295,"g7z8v1","Бегство от реальности"],[296,"vqmzi0","Требует наследство раньше времени и спускает его на немедленные ощущения: обмен Рувима в чистейшем виде. Дальняя страна даёт ровно то, что заказал аппетит, пока не приходит голод, и свинарник всё расставляет по местам."],[297,"19ubq5n","«Опомнившись», аппетит наконец говорит правду о том, чего он дать не может. Отец бежит навстречу, одежда и перстень возвращают сыновство, а пир доказывает, что наследство никогда не было про деньги."],[298,"jw3450","Неустойчивость Рувима"],[299,"hwwizb","Быт. 35:22"],[300,"ykwp6n","Патриарх"],[301,"enpe5u","Наследник-первенец"],[302,"5yeqsp","Защитник (Быт. 37)"],[303,"1hp1e1m","Страстность"],[304,"t3j50t","Неустойчивость"],[305,"8dpv4l","Импульсивность"],[306,"1iubbo7","Осквернение"],[307,"vg9oel","Действует на чистом биологическом порыве: ложится с наложницей отца. Полностью пренебрегает весом и святостью своего поступка для поколений ради мгновенного всплеска."],[308,"utfjyg","Полностью теряет благословение первенца. Остаётся навсегда структурным предупреждением: неуправляемый аппетит проматывает наследство и заставляет следующие поколения управлять тем, чем он управлять не стал."],[309,"xwvjkj","Радость ⇌ Депрессия"],[311,"h5s9lp","Радость"],[312,"14wwcqc","Способность видеть красоту там, где другие видят пепел. Созвучие с Богом. (Неем. 8:10)"],[313,"18zczwh","Депрессия"],[314,"o17jpb","Подсознательно рана милее исцеления. (Притч. 12:25)"],[315,"ipyfcw","Неффалим"],[316,"alff0k","Лань"],[318,"1g0tjtt","«Неффалим — выпущенная на свободу лань, которая приносит прекрасных детенышей». — Быт. 49:21"],[319,"i5wgpu","Бегство"],[320,"1hqe9o2","Довольство"],[321,"fm50q8","Радость"],[322,"1b1www8","Творчество"],[323,"trisde","Освобождение"],[324,"1hqh97m","Художественный дар"],[325,"i5wgpu","Бегство"],[326,"1xlt6bn","Роль жертвы"],[327,"120t6vr","Изоляция"],[328,"1u87g4d","Исцеление"],[329,"1wge6m3","Эмпатия"],[330,"vpcuq8","Освобождение"],[331,"p8yu1q","Варак"],[332,"h63wis","Мария Магдалина"],[333,"1n4ckdq","Гадаринский бесноватый"],[334,"1n28uve","Больной у Вифезды"],[335,"undsd5","Иона"],[336,"1rqvl8c","Асаф"],[337,"82dmpa","Иеремия"],[339,"1qzv93y","«Выпущенная на свободу лань»: освобождённые освобождают других. Опасность в том, чтобы играть свою рану вместо того, чтобы свидетельствовать."],[340,"1v8ogkf","В рабстве у раны: диагноз становится идентичностью, гробницы становятся домом, а любую структуру, которая могла бы исцелить, ты называешь клеткой."],[341,"nor9pi","Бог применяет любящее ограничение: кит, ожидание, вопрос «Ты хочешь выздороветь?», пока знакомая боль наконец не станет менее притягательной, чем незнакомая свобода."],[342,"v677cy","Лань, выпущенная на высоты: та же чувствительность, что впитывала тьму, теперь приносит прекрасный плод, о котором говорит благословение (Быт. 49:21), — свидетельство, которое открывает двери другим узникам. Варак из колена Неффалима (Суд. 4:6) двигается, когда его зовут."],[343,"192k7g1","Атака приходит в тот момент, когда появляется настоящая подотчётность: трудное слово, срок, обязательство завета. Именно тогда всё внутри кричит «беги» (Иона 1:3)."],[344,"woqdl6","Прорыв выглядит так: ты остаёшься. Сидишь в неудобстве «клетки», пока она не окажется дверью. Гадаринец освободился, и ему велели идти домой, туда, откуда он больше всего хотел уйти."],[345,"tyfg4f","Джон Беньян"],[346,"1lsd5j2","XVII в."],[347,"1kkvdil","Выбрал двенадцать лет в тюрьме Бедфорда, лишь бы не соглашаться перестать проповедовать. Из этих заключений родилось «Путешествие пилигрима», книга о свободном пути, написанная человеком, который не мог выйти из комнаты."],[348,"i1264g","Уильям Купер"],[349,"u4uh1x","XVIII в."],[350,"1xyrkor","Всю жизнь боролся с суицидальной депрессией и из неё написал гимн «Бог действует таинственно»: доказательство, что борьба и дар могут жить в одном сердце."],[351,"1w7qg08","Уязвимость как оружие (вываливание травм на других как трибуна или защита)."],[352,"t966et","Сопротивление здоровым структурным границам: ты называешь их «клетками» или «токсичными»."],[353,"1q0hbm3","Подсознательно предпочитаешь привычную рану ответственности настоящего исцеления."],[354,"1yekqbe","Пропадаешь из жизни друзей или церкви, как только появляется здоровое трение."],[355,"10a1pi7","Зависимость от меланхолии и грустного контента, потому что это кажется «настоящим»."],[356,"ol4c9l","Так сильно отождествляешь себя со своим психиатрическим диагнозом, что активно защищаешь его от исцеления."],[357,"8a8uid","Настоящее исцеление (а не его спектакль)."],[358,"fkhtnx","Дух уныния"],[359,"1s176jh","Запирает способность к сопереживанию в бесконечном цикле переживания боли, так и не пуская к настоящему освобождению."],[360,"1n898co","Ободряющий"],[361,"18hjrw1","Сирота (без корней)"],[362,"7amme0","Одобрение и комфорт"],[363,"12i9lez","Уныние"],[364,"dnle00","«Свобода значит никогда не проводить жёстких границ и не подчиняться структуре»."],[365,"1aktdbv","<strong>Путь священника:</strong> принять необходимое трение правды и настоящего исцеления; разрушить алтарь бегства, построив устойчивый алтарь довольства."],[366,"hqdwaz","Выгорание от избегания: огромная энергетическая цена постоянного бегства от нужного трения или конфликта."],[367,"1n5b2sh","Обрываешь самые ценные партнёрства, как только появляется структурная подотчётность."],[368,"1ozlm0k","Бегство: потребление новых мест, новых отношений или новых идей, чтобы не оседать и не делать работу. (Притч. 18:1)"],[369,"1g5egfb","Активное освобождение: глубокая эмпатия, которая исцеляет и освобождает других внутри надёжных обязательств."],[370,"1ib7ax4","Сильная клаустрофобия; парализующая телесная тяжесть, которая убеждает, что двинуться невозможно."],[371,"jxjm0h","Сиротская рана бездомности: глубокий ужас оказаться прижатым, под контролем или в ловушке боли без выхода."],[372,"1dzs5e0","Мимолётный прилив «свободы», когда бросаешь трудное обязательство."],[373,"jo4xgs","Ощущение физической ловушки или поверхностное дыхание, когда просят назвать жёсткий срок или взять обязательство."],[374,"1e09nmp","Трение с Завулоном (Купец): его одержимость метриками и бухгалтерией кажется Неффалиму удушающей клеткой."],[375,"1p5aom3","Не собирай чемоданы. Не отправляй сообщение. Посиди в неудобстве «клетки» и назови точный страх."],[376,"1q85vtk","Понять, что настоящая свобода находится только *внутри* завета и структуры, а не в постоянном бегстве от них."],[377,"p6glcl","Обязаться одной поместной общине, одной работе или одним главным отношениям на неизменный срок в 3 года."],[378,"134zyp","Разрушить алтарь бегства, построив алтарь довольства: находить глубокую радость и свободу в обыденных, ежедневных повторениях жизни."],[379,"1fyr6wv","Бегство Ионы"],[380,"1oly9il","Иона 1:3"],[381,"12foxhd","Пророк"],[382,"1pgy10k","Вестник"],[383,"on0zzx","Чуткость к Духу"],[384,"xz61dd","Правдивость"],[385,"1cvr3rr","Избегание"],[386,"1nlodv0","Предубеждение"],[387,"1yg9mkm","Жалость к себе"],[388,"qkc5cg","Отказывается нести тяжёлое, чёткое поручение: сказать Ниневии трудное слово. Сбегает на корабль и отключается, засыпая в трюме посреди огромного бедствия."],[389,"xw1lry","Буря и кит: Бог вводит строгое, неизбежное ограничение, чтобы привести к покаянию. Иона подчиняется именно тому поручению, от которого бежал, и передаёт слово, не смягчая его ради удобства."],[390,"1ckybxd","Больной у Вифезды"],[391,"16z917r","Ин. 5:6"],[392,"cv0akm","Свидетельство благодати"],[393,"dkm0js","Терпеливый (не туда)"],[394,"1xlt6bn","Роль жертвы"],[395,"1ld5uhd","Оправдания"],[396,"19c993f","Самоуспокоенность"],[397,"17m6f1m","38 лет в ловушке паралича: болезнь стала его стержневой идентичностью. Он всё время объясняет, почему исцеление невозможно: «нет никого, кто бы помог мне войти в воду»."],[398,"2gmyrw","Иисус прямо бросает вызов: хочет ли он настоящего исцеления больше, чем удобства раны? «Ты хочешь выздороветь?» Он встаёт и уходит из привычной, удобной идентичности жертвы."],[399,"1n4ckdq","Гадаринский бесноватый"],[400,"1b1wnz1","Мк. 5:15"],[401,"1wtwpv9","Евангелист"],[402,"caej8i","Живое свидетельство"],[403,"fv8cun","Восстановлен"],[404,"18tdk89","Послушание"],[405,"6zmqr7","Свидетельствует"],[406,"rsv0n6","Саморазрушение"],[407,"1ck9ag2","Изоляция"],[408,"16ezdib","Мучения"],[409,"1coxu3u","Полностью одержим легионом уныния, режет себя, живёт один среди гробниц. Рвёт любые цепи человеческих структур и требует полной, хаотичной «свободы» через безумие."],[410,"d0apl5","Иисус велит легиону уныния выйти. Человека находят одетым и в здравом уме, сидящим у ног Иисуса, и тут же посылают благовествовать в своём городе."],[411,"cp06al","Владычество ⇌ Запугивание"],[413,"f03hn2","Владычество"],[414,"nmae2z","Власть, данная на служение. Сила, которая защищает, а не пожирает. (Пс. 71:8)"],[415,"r5gqim","Запугивание"],[416,"1uzqnvk","Правление через страх. Пожирать союзников, лишь бы остаться наверху. (1 Пет. 5:3)"],[417,"yxek91","Иуда"],[418,"137db9q","Лев"],[420,"wjczwf","«Ты — молодой лев, Иуда… Скипетр не покинет Иуду». — Быт. 49:9–10"],[421,"1qil6yv","Культ переработки"],[422,"1v5ei3y","Чистота в правлении"],[423,"lp6xf8","Мужество"],[424,"1dr6uv8","Авторитет"],[425,"gdjtiy","Хвала"],[426,"1avpcxx","Визионер"],[427,"1pegfct","Гордость"],[428,"1107kxb","Нарциссизм"],[429,"13rkbwl","Показуха"],[430,"1lpr1ly","Власть"],[431,"1ttdqrf","Ответственность"],[432,"tknmq7","Мужество"],[433,"1tbepx4","Царь Давид"],[434,"10fv3fn","Иосия"],[435,"1rujmai","Езекия"],[436,"1hfgrud","Царь Озия"],[437,"ny93p3","Царь Ровоам"],[438,"1wkeiru","Стефан"],[440,"1d9u73v","Рождён править и посылать. Опасность в царстве, построенном как зеркало царя."],[441,"gvbn87","В рабстве у софитов: значимость измеряется заметностью, а ценность рушится в тот миг, когда рушится сцена."],[442,"1c252ew","Бог тебя прячет: пещера Адуллам, годы между помазанием и троном. Ты учишься быть царём втайне, прежде чем стать царём на виду."],[443,"1mgkox0","Скипетр в открытых ладонях: власть тратится на то, чтобы защищать и возвышать других, а хвала отдаётся наверх. Лев, которому хватает силы преклонить колени."],[444,"8ev36x","Атака приходит в праздности после победы: «Весной, когда цари идут на войну… Давид же оставался в Иерусалиме» (2 Цар. 11:1). Лев без настоящей ноши всё равно на кого-то охотится."],[445,"12xvcmo","Прорыв выглядит так: ты принимаешь своего Нафана. Держишь рядом хотя бы один голос, которому достаточно близко и безопасно сказать «Ты — тот человек!», и каешься публично, даже когда это стоит тебе имиджа."],[446,"25wrjw","Чарльз Сперджен"],[447,"liiwl4","XIX в."],[448,"1nr95l","Самый известный проповедник своего века, за кафедрой боровшийся с тяжёлой депрессией. Понял, что корона принадлежит Другому, и говорил об этом из низины."],[449,"evq8ub","Билли Грэм"],[450,"syhnso","XX в."],[451,"wpkg2d","Увидел, что сцена делает со львами, и в 1948 году, ещё до прихода славы, составил «Манифест Модесто»: письменные ограничители в деньгах, сексуальной чистоте, честной рекламе и отказ нападать на другие церкви."],[452,"7317p6","Тяжёлая, сокрушительная депрессия, когда исчезают софиты или сцена."],[453,"15qs2fp","Используешь людей, отношения или площадки лишь как лестницы, чтобы питать чувство собственной значимости."],[454,"164rl15","Путаешь публичную заметность с настоящим духовным авторитетом и здоровьем."],[455,"12iba0s","Когда нет миссии, срываешься в тайные желания (праздность рождает потребление)."],[456,"1s2nfyj","Необъяснимая пустота сразу после огромного публичного успеха."],[457,"1ydsv1i","Втайне ведёшь счёт, кто признаёт твой вклад, а кто нет."],[458,"1kvn9tz","Настоящая ответственность с настоящим весом."],[459,"cu8gj5","Иезавель / Нарциссизм"],[460,"1scpy7k","Присваивает власть через запугивание. Превращает рык призвания в механизм правления страхом."],[461,"iqoavn","Руководитель"],[462,"19gyzh","Вдова (утрата царства)"],[463,"1jamndy","Власть"],[464,"pho9h3","Иезавель/Нарциссизм"],[465,"436elg","«Моя значимость полностью зависит от того, насколько меня видно»."],[466,"fzijrb","<strong>Путь царя или царицы:</strong> руководить из покоя, а не из публичного выступления; давать силу и поручать другим; разрушить алтарь культа переработки, чтобы найти свою ценность за пределами заметности."],[467,"1w0cgu7","Выгорание от сцены: истощение от постоянного производства образа, который нужен, чтобы удерживать софиты."],[468,"16vqtzm","Комплекс «одиноко на вершине»: вокруг льстецы, а эмоциональной связи нет ни с кем."],[469,"1xnkhcb","Завоевание и притязание: уверенность, что ресурсы, люди и слава организации существуют, чтобы питать его значимость. (3 Ин. 9)"],[470,"1m9eeen","Жертвенная власть: использовать силу, чтобы защищать, укреплять и возвышать подчинённых."],[471,"jvsd4s","Токсичное чувство притязания под видом «предназначения»; глубокое, жгучее раздражение, когда тебя не признают или не уступают тебе сразу."],[472,"1db6z1a","Рана вдовы, утратившей царство: подсознательный ужас стать невидимым, ненужным или заменимым."],[473,"nkiwu3","Адреналиновый всплеск от публичных аплодисментов и непререкаемой власти."],[474,"1urdi23","Вспышка сильного гнева или жар в лице, когда публичную похвалу за общую победу получает кто-то другой."],[475,"gwyufv","Трение с Даном (Судья): Иуда ненавидит критику, а Дан мастерски находит роковые изъяны."],[476,"1x3k9f6","Публично переадресуй похвалу. Заставь себя вслух похвалить конкретный вклад подчинённого."],[477,"yuic8s","Принять правду, что настоящее сыновство утверждается в тайной комнате, совершенно независимо от публичных результатов или метрик."],[478,"ol5k00","Вводить обязательные сезоны анонимности: давать, служить и строить там, где получить признание структурно невозможно."],[479,"qxxs4z","Заменить алтарь переработки и показухи алтарём чистоты: руководить из надёжной идентичности, а не хвататься за завоевания."],[480,"1q5kd5j","Давид у окна"],[481,"188ur2f","2 Цар. 11:1"],[482,"i0u8dy","Царь"],[483,"1nmvlm","Поклоняющийся"],[484,"1oj2ihy","Покаяние"],[485,"9uyi1u","Сердце для Бога"],[486,"8cjnxc","Похоть"],[487,"jbuwmr","Праздность"],[488,"8dpv4l","Импульсивность"],[489,"11z2ytd","Отказывается нести положенный сезону груз (остаётся дома во время войны). Праздность ведёт к чувству притязания: «Я царь, я могу взять то, что вижу» (Вирсавия)."],[490,"pcehc3","Пророк Нафан с помощью точно выбранной притчи обходит нарциссическую защиту Давида. Глубокое публичное покаяние и возвращение к простому, смиренному служению Богу вместо самосохранения."],[491,"13hvox1","Гордость царя Озии"],[492,"1s1gnd4","2 Пар. 26:16"],[493,"i0u8dy","Царь"],[494,"tn5ckg","Строитель"],[495,"1s4lfz5","Новатор"],[496,"12wbgrs","Военная сила"],[497,"ee7ykv","Высокомерие"],[498,"la50yh","Самонадеянность"],[499,"zqq4qr","Неспособность учиться"],[500,"mtan5k","Огромный организационный и военный успех ведёт к сильному внутреннему чувству притязания. Он верит, что царская власть позволяет ему присвоить священническое служение каждения."],[501,"1jcvrts","Поражён проказой в тот самый миг, когда пришёл в ярость на священников, которые его поправляли. Не смог развернуться: до самой смерти жил отдельно, прокажённым, лишённым всякой власти."],[502,"h56vda","Тяжёлая рука Ровоама"],[503,"skyese","3 Цар. 12:14"],[504,"1f8l43x","Наследник"],[505,"nwem1d","Царь Иудеи"],[506,"1qn289y","Унаследованная мудрость (сначала)"],[507,"y39ycw","Запугивание"],[508,"vxrvr7","Жёсткость"],[509,"1bax40z","Неуверенность"],[510,"u1hz4","Отвергает совет старейшин служить народу. Пытается править только страхом и запугиванием, угрожая наказывать скорпионами вместо плетей."],[511,"1s8va62","Царство резко раскалывается. Он теряет десять колен, потому что выбрал идола абсолютной власти и запугивания вместо призвания к служащему лидерству. Власть утрачена навсегда."],[512,"fhuquu","Иосиф"],[513,"oq4dsl","Бык"],[515,"17ujebp","«Иосиф — плодородная виноградная лоза, плодородная лоза близ источника, чьи ветви поднимаются по стене». — Быт. 49:22"],[516,"10tp7xw","Броня"],[517,"jmduou","Прощение"],[518,"rwyk5b","Администратор"],[519,"jsjwh0","Стойкость"],[520,"1048362","Верность"],[521,"6fgteq","Строитель систем"],[522,"120t6vr","Изоляция"],[523,"1e0sbqr","Непрощение"],[524,"12z3dim","Глухая стена"],[525,"13wux9r","Управление"],[526,"6wrg3b","Порядок"],[527,"138vxnw","Стойкость"],[528,"fhuquu","Иосиф"],[529,"16tfhba","Старший брат"],[530,"j5gshc","Нееман Сириянин"],[531,"nmmdzm","Лука"],[532,"15fzmo4","Даниил (на службе)"],[534,"zu89mf","Строит системы, которые проводят народы через голод. Опасность в системах, построенных как стены против людей."],[535,"z899fw","Буквально Египет: предан родными, продан братьями, заключён в тюрьму по ложному обвинению. Все причины навсегда облачиться в броню."],[536,"1bavl0w","Годы тюрьмы: верность, которую никто не видит, управление без награды, прощение, отрепетированное задолго до того, как о нём попросят."],[537,"1ypdy0p","«Вы замыслили против меня зло, но Бог обратил его ко благу» (Быт. 50:20): броня снята, житницы открыты, и преданный становится кормильцем тех, кто его предал."],[538,"1bvrndu","Атака приходит, когда кто-то подходит достаточно близко, чтобы снова ранить: близость захлопывает дверь сейфа (Быт. 42:7, Иосиф сурово говорит с братьями, над которыми потом будет плакать)."],[539,"16ylh3n","Прорыв выглядит так: ты плачешь перед теми, кого проверял, и отпускаешь список обид, всё ещё занимая положение, в котором мог бы свести счёты."],[540,"1vbz8ix","Корри тен Бом"],[541,"syhnso","XX в."],[542,"zg3ygv","Преданная и заключённая в Равенсбрюк, она позже встретила лицом к лицу одного из охранников лагеря. «Прощение — это акт воли», и её рука протянулась первой."],[543,"1688v32","Ричард Вурмбранд"],[544,"syhnso","XX в."],[545,"16ri1eo","Четырнадцать лет пыток в коммунистических тюрьмах; вышел, проповедуя любовь к своим мучителям. Броня обменяна на раны, которые исцеляли других."],[546,"jod9s7","Глухая стена перед близкими и партнёрами, чтобы полностью исключить возможность предательства."],[547,"5iwap6","Гипернезависимость и глубокая изоляция под видом «эффективности» или «стойкости»."],[548,"u092q1","Подсознательно устраиваешь друзьям и партнёрам невыполнимые проверки на верность."],[549,"ixuxlw","Вычёркиваешь людей навсегда после одной ошибки (нулевая терпимость к промахам)."],[550,"e9ziz1","Для каждых отношений у тебя продумана тайная «стратегия выхода»."],[551,"1p2g8ox","Перегружаешь себя логистикой и администрированием, лишь бы не соединяться эмоционально."],[552,"1rsshk5","Упорядоченная работа с настоящей ношей внутри безопасных отношений."],[553,"ucwbv3","Изоляция / Контроль"],[554,"1m9g3vd","Использует прошлое предательство, чтобы оправдать непроницаемые эмоциональные стены, отсекая уязвимость, без которой нельзя вести."],[555,"iqoavn","Руководитель"],[556,"14bkm3q","Вдова (утрата порядка)"],[557,"1w49xzd","Власть и контроль"],[558,"83z76l","Изоляция/Контроль"],[559,"rm415d","«Боль нужно идеально управлять и держать под контролем»."],[560,"mxc6rp","<strong>Путь царя или царицы:</strong> опустить эмоциональную броню и рискнуть уязвимостью в безопасных, заветных отношениях; вести с сердцем прощения, а не со щитом контроля."],[561,"1kb61ei","Усталость от глухой стены: огромная энергетическая цена непроницаемой эмоциональной брони 24/7."],[562,"4zcfku","Тактическое, намеренное устранение всех уязвимых точек соприкосновения; отсечение каждого, кто не прошёл проверку на верность."],[563,"1i3t4xd","Контролируемая близость: отношения, выстроенные так, что вся власть у Иосифа и он не рискует ничем эмоционально. (Притч. 18:19)"],[564,"10qwb68","Уязвимое управление: строить устойчивые системы и сохранять открытые, прощающие отношения."],[565,"sgcbpc","Холодная, расчётливая отстранённость; полное онемение, анализ и стена между тобой и человеческой неразберихой."],[566,"wiebrl","Рана вдовы от глубокого предательства близкой семьи или руководства; клятва, что «больше никто никогда не сможет меня ранить»."],[567,"1wkeych","Холодная, стерильная безопасность полной неуязвимости."],[568,"12ejp17","Внезапный внутренний холод или эмоциональное «отключение», когда кто-то задаёт глубокий личный вопрос."],[569,"14ac31j","Трение с Вениамином (Волк): хаотичная напористость Вениамина постоянно угрожает отлаженным системам Иосифа."],[570,"nlmn7z","Не прячься в данные. Заставь себя смотреть в глаза. Скажи вслух: «Сейчас я защищаюсь»."],[571,"xn5f6k","Принять, что непроницаемая эмоциональная броня не пропускает ни боль, *ни* уязвимость, без которой невозможно настоящее, помазанное лидерство."],[572,"19704c6","Назначить ежедневные короткие встречи, посвящённые исключительно *чувствам* и личному опыту, без списков задач и метрик."],[573,"3lnwnr","Разрушить алтарь брони (глухой стены) и построить алтарь прощения, сознательно отпуская список обид на тех, кто предавал в прошлом."],[574,"1ef0v3d","Иосиф испытывает братьев"],[575,"m7e106","Быт. 42:7"],[576,"1d03gh6","Администратор"],[577,"1e8aosm","Спаситель народов"],[578,"jsjwh0","Стойкость"],[579,"1s7uf08","Блестящий ум"],[580,"1yyx6gz","Чистота"],[581,"u1jhss","Контроль (сначала)"],[582,"1z0cyes","Сдержанность"],[583,"11cuqdm","Несёт неисцелённую рану глубокого предательства родной кровью. Использует огромную административную власть, чтобы жёстко проверить братьев, прежде чем рискнуть уязвимостью."],[584,"139s8ql","Иуда предлагает свою жизнь вместо Вениамина и доказывает, что братья изменились. Броня Иосифа полностью рушится: он громко плачет и объявляет прощение."],[585,"16tfhba","Старший брат"],[586,"18i72b8","Лк. 15:28"],[587,"9ek8kz","Управляющий"],[588,"45ly4y","Верный сын"],[589,"16raehe","Преданность"],[590,"1ml19mf","Трудолюбие"],[591,"18tdk89","Послушание"],[592,"1li3qor","Горечь"],[593,"7dzxb6","Законничество"],[594,"1ybjdcm","Эмоциональная отстранённость"],[595,"no0cat","Глубокая внутренняя горечь под видом безупречной административной верности Отцу. Делает всю работу, но всей душой презирает благодать, когда её дают недостойным."],[596,"dyfz4e","Отец выходит с праздника и уговаривает его в поле. Его приглашают отпустить список обид и войти в шумную, неуправляемую радость дома."],[597,"j5gshc","Нееман Сириянин"],[598,"1go2t1m","4 Цар. 5:11"],[599,"qkms9x","Военачальник"],[600,"nov4ln","Полководец"],[601,"1cavly3","Достоинство"],[602,"1papfdy","Победоносность"],[603,"xo9vl3","Способность"],[604,"quagdl","Гордость"],[605,"2e07yk","Негибкость"],[606,"1gcrt7a","Обида"],[607,"1p5dq4v","Ожидает чёткого, достойного, административного процесса исцеления. Глубоко обижен, когда ему велят омыться в грязной реке, и чуть не уходит от своего чуда из-за глухой стены гордости."],[608,"k4io1p","Прислушивается к мудрости слуг, снимает броню и обиду, окунается семь раз, и его плоть полностью восстанавливается, как у ребёнка."],[609,"1wbybqd","Вениамин"],[610,"f250as","Волк"],[612,"1xghkqu","«Вениамин — прожорливый волк; утром он пожирает добычу…» — Быт. 49:27"],[613,"1lc7mb5","Преданность"],[614,"sfh0lr","Война по поручению"],[615,"gr9nxn","Неистовость"],[616,"16raehe","Преданность"],[617,"fc2ybl","Прорыв"],[618,"1g4c6mu","Ревность"],[619,"f65dio","Гнев"],[620,"1pbx5n2","Паранойя"],[621,"muxds6","Раздоры"],[622,"n84iay","Напористость"],[623,"fc2ybl","Прорыв"],[624,"1lc7mb5","Преданность"],[625,"i1qec1","Апостол Павел"],[626,"llu04c","Ионафан"],[627,"x6ie95","Аод"],[628,"h7a1m5","Мардохей"],[629,"12i2733","Царь Саул"],[630,"l2h7ud","Иоав"],[631,"hnqshc","Авесса"],[633,"uqexeu","Волк, который охраняет стадо: под клыками скрыт дар милосердия. Опасность в клыках, обращённых на овец."],[634,"1wnbwp5","В рабстве у карты угроз: каждый под подозрением, каждая мелочь как объявление войны, союзников съедают по одному подозрению."],[635,"x3zczw","Дорога в Дамаск: ослеплённого ведут за руку, а исцеляет его та самая община, на которую он охотился. Напор сломлен, чтобы его можно было навести заново."],[636,"1uuenzc","Война по поручению: «прожорливый волк», нацеленный на настоящую тьму. Ярость Павла пишет половину Нового Завета, верность Ионафана идёт против паранойи собственного отца."],[637,"9k16bm","Атака приходит через мнимую обиду от союзника: нейтральное замечание прочитано как измена, друг за одну ночь переписан во враги (1 Цар. 18:9, «С тех пор Саул стал с подозрением смотреть на Давида»)."],[638,"4aahvd","Прорыв выглядит так: 24-часовое перемирие на тот выстрел, в правоте которого ты уверен. Прежде чем стрелять, спросить: «Враг или союзник, который оступился?», и найти свою настоящую битву в другом месте."],[639,"i7gzw2","Уильям Бут"],[640,"liiwl4","XIX в."],[641,"1s6k6t7","«Пока женщины плачут, как плачут сейчас, я буду сражаться». Основал Армию спасения, направив волчий напор на бедность и тьму, а не на церковную политику."],[642,"pqd3ee","Джеки Пуллинджер"],[643,"syhnso","XX в."],[644,"1pfy329","Одна вошла в Обнесённый стеной город Коулуна и пятьдесят лет вытаскивала наркозависимых из пасти дракона. Одна битва по поручению, доведённая до конца."],[645,"loi0a4","Разрываешь давние отношения из-за мнимых обид или мелких проступков."],[646,"4b0ejs","Не можешь отдыхать, потому что всегда есть «война, которую надо выиграть» или кто-то, кто под тебя копает."],[647,"tpyrd4","За одну ночь превращаешь бывших близких союзников в смертельных врагов (огонь по своим)."],[648,"1bm41ji","Паранойя, что самые близкие люди сговариваются против тебя."],[649,"17oho8g","Постоянно проверяешь людей на верность, пока они неизбежно не провалятся."],[650,"ltm05x","Используешь природный напор и силу слова, чтобы запугиванием добиваться от других подчинения."],[651,"dhzr7w","Ясный враг, определённый Богом. Посланность в правильную битву."],[652,"zckl1b","Пожиратель / Паранойя"],[653,"8whfg5","Уводит святую агрессию от настоящего врага к союзникам и устраивает непрерывный огонь по своим."],[654,"x5gr6v","Милосердие"],[655,"1xreg1r","Вдова (эмоциональное насилие)"],[656,"hiz9w8","Комфорт и власть"],[657,"rjo539","Пожиратель"],[658,"1jajguy","«Уязвимость значит слабость, и она меня погубит»."],[659,"190k4tu","<strong>Путь священника и царя:</strong> выстроить святые эмоциональные границы; отвести неистовый напор от союзников и вести активную войну по поручению против настоящего духовного врага."],[660,"glbkpg","Выгорание от конфликтов: истощение от жизни в состоянии постоянной выдуманной войны."],[661,"1mmbaxv","Изоляция выжженной земли: сожжённые мосты с верными союзниками из-за внезапной, сильной паранойи."],[662,"1hsw5y4","Напор и раздоры: зависимость от адреналина конфликта; нужен «враг», чтобы чувствовать себя живым. (Притч. 17:14)"],[663,"9yzm4n","Война по поручению: неистовый, прорывной напор, направленный только на настоящие бесовские структуры."],[664,"1ylj3n1","Сверхбдительный выброс адреналина; нейтральные замечания читаются как серьёзные угрозы, требующие немедленного и сокрушительного ответа."],[665,"81aoxc","Рана вдовы от эмоционального насилия; глубоко укоренившаяся уверенность, что все тайно строят против тебя заговор."],[666,"1548m7g","Острая, собранная ясность, которая приходит, когда есть чётко определённый враг для атаки."],[667,"nayf2n","Расширенные зрачки и мгновенное напряжение в корпусе, когда кто-то не соглашается в мелочи."],[668,"18wuhh9","Трение с Асиром (Хозяин): миротворчество Асира кажется слабым, трусливым компромиссом."],[669,"197sax0","Не стреляй. Положи телефон. Спроси себя: «Это настоящий враг или просто союзник, который ошибся?»"],[670,"b519d7","Понять, что огонь по своим всё равно убийство, а напор без различения разрушает то самое царство, которое ты пытаешься защитить."],[671,"15mwfe6","Ввести обязательную 24-часовую паузу, прежде чем отвечать на любую мнимую обиду, письмо или конфликт в отношениях."],[672,"1dcwb2u","Снести алтарь слепой верности (который порождает паранойю) и поставить алтарь войны по поручению: направлять силу только туда, куда указывает Бог."],[673,"9769c9","Саул охотится на Давида"],[674,"rz6uel","1 Цар. 18:9"],[675,"i0u8dy","Царь"],[676,"ed399l","Воин"],[677,"xo9vl3","Способность"],[678,"12wbgrs","Военная сила"],[679,"1qpv63x","Паранойя"],[680,"1bax40z","Неуверенность"],[681,"158vq4n","Жажда убийства"],[682,"n38b1z","Глубокую неуверенность запускает чужое помазание (песня о Давиде). Все ресурсы царства брошены на охоту за самым верным слугой из-за параноидальной неуверенности."],[683,"l8ent4","Давид щадит жизнь Саула в пещере, показывая неоспоримую, неугрожающую верность. Саул так и не отвёл свой неистовый напор от союзников навсегда, и это стоило ему династии."],[684,"1time12","Жестокая верность Иоава"],[685,"1phkj4q","2 Цар. 3:27"],[686,"nov4ln","Полководец"],[687,"qkms9x","Военачальник"],[688,"etm3kh","Яростная верность"],[689,"mkhqb8","Тактика"],[690,"5m4wh9","Мстительность"],[691,"18kpm52","Непокорность"],[692,"1430cao","Жестокость"],[693,"nyd7od","Всё, что угрожало правлению Давида (или положению Иоава), видит врагом, которого надо уничтожить. Убивает Авенира в мирное время из мести и неистовой, никем не санкционированной верности."],[694,"1kw8ks5","Давид публично оплакивает Авенира и отстраняется от кровавых методов Иоава. Не смог развернуться: в конце концов Соломон казнит Иоава за то, что тот так и не обуздал свою жестокость."],[695,"14c6ljn","Савл из Тарса"],[696,"l5kwe","Деян. 9:1"],[697,"amas70","Фарисей"],[698,"zblh8h","Апостол"],[699,"1s7uf08","Блестящий ум"],[700,"1g4c6mu","Ревность"],[701,"1sp2f7f","Целеустремлённость"],[702,"158vq4n","Жажда убийства"],[703,"1qpv63x","Паранойя"],[704,"1430cao","Жестокость"],[705,"1wfr57g","Дышит угрозами и убийством на учеников, веря, что его жестокость есть святой крестовый поход, защищающий Бога от еретической секты-отступницы."],[706,"1nq6pkn","Ослеплён на дороге в Дамаск. Дух Пожирателя сокрушён благодатью Иисуса, и неистовый напор Савла навсегда направлен на написание Нового Завета."],[707,"7sw6e6","Симеон"],[708,"mrk5lq","Клинок"],[710,"cw2uab","«Симеон и Левий, братья: их мечи — орудие насилия». — Быт. 49:5"],[711,"1qydmoe","Ревность без поручения"],[712,"195inp0","Ревность по поручению"],[713,"1g4c6mu","Ревность"],[714,"1yyx6gz","Чистота"],[715,"39rjx0","Готовность"],[716,"1xomwc4","Убеждённость"],[717,"1m951oj","Ярость"],[718,"1y8thil","Жестокость"],[719,"89t5ho","Горечь"],[720,"43dgr9","Ревность"],[721,"tsw84w","Чистота"],[722,"1nqh57j","Готовность"],[723,"1grxsza","Симеон и Левий"],[724,"8nvqq","Сыны грома (Иаков и Иоанн)"],[725,"1xf24nr","Финеес"],[726,"o90lio","Илия (на Кармиле)"],[727,"12oyjuf","Пётр (с мечом)"],[728,"1hwd29b","Ииуй"],[730,"11o415f","Ясно видит нечистое и горит желанием его вычистить. Опасность в чистоте, после которой не остаётся выживших."],[731,"1t2f56c","В рабстве у возмущения: каждая нечистота как личный вызов, каждое несогласие как дело о смертной казни, а позади остаются истекающие кровью общины."],[732,"ndnmd","«Вы не знаете, какого вы духа»: упрёк, который отделяет ревность от жестокости, и долгая практика молиться о благословении для тех, кто, казалось бы, заслужил удар."],[733,"1k0sljr","Путь левитов, искупленный: то самое колено, что устроило резню в Сихеме, потом встаёт рядом с Моисеем и наследует священство (Исх. 32:26–29). Клинок наконец под приказом."],[734,"19id9f0","Атака приходит, когда ты видишь настоящий проступок: реальная вина служит приманкой, а ловушка в несоразмерном ответе (Быт. 34, бесчестье, на которое ответили резнёй)."],[735,"1xxyyac","Прорыв выглядит так: ты молишься о восстановлении того, чей грех мог бы разоблачить. Меч в ножнах не потому, что факты неверны, а потому, что милость выше точности."],[736,"3vwz1","Уэсли и Уайтфилд"],[737,"u4uh1x","XVIII в."],[738,"1936iat","Горько разошлись в учении и годами спорили в печати; Уайтфилд попросил Уэсли проповедовать на своих похоронах. Соперники, которые закончили почтением, показывают, как выглядит обузданная ревность."],[739,"1a9m1az","Элизабет Эллиот"],[740,"syhnso","XX в."],[741,"eqo8ca","Её мужа убили копьями индейцы ваодани; она переселилась в их деревню с маленькой дочерью и Евангелием. Месть отвергнута, народ преображён."],[742,"mthnvk","Конфликты до выжженной земли из-за мелких богословских или методологических разногласий."],[743,"1xuezwf","Оправдываешь откровенную жестокость «праведной ревностью» или тем, что «просто говоришь горькую правду»."],[744,"1kt7gfi","Интернет-травля, перепалки или толпы «культуры отмены» под видом чистоты."],[745,"1a6m1i5","За тобой тянется длинный след разрушенных, истекающих кровью общин."],[746,"4suxfg","Навсегда вычёркиваешь людей из жизни из-за одного разногласия."],[747,"s9ks1f","Прилив адреналина и самоправедности, когда «разоблачаешь» чужой грех."],[748,"14dh87y","Цель, указанная Богом и ограниченная милостью."],[749,"mhamvl","Ревность без милости"],[750,"1zl4fm","Прикрывается маской «праведной правды», чтобы оправдать откровенную жестокость и разрушение общин."],[751,"x5gr6v","Милосердие"],[752,"1jrerwg","Вдова (тяжёлая утрата)"],[753,"10fbl8e","Контроль"],[754,"mhamvl","Ревность без милости"],[755,"qjepbo","«Ревность полностью оправдывает уничтожение всего, что я считаю нечистым»."],[756,"1peheac","<strong>Путь священника и царя:</strong> выстроить святые эмоциональные границы; поднимать клинок ревности только по Божьему поручению и смягчать любой суд радикальной милостью."],[757,"1kip4hx","Выгорание от возмущения: духовная сухость от постоянного гнева под видом праведности."],[758,"rkcpfr","Одиночество палача: его все боятся, но никто не любит."],[759,"1izv8fh","Мщение и жестокость: аппетит к тому, чтобы наказывать других и смотреть на их крах под видом «справедливости». (Иак. 1:20)"],[760,"1uxym8i","Обузданная ревность: святая готовность и чистота, полностью ограниченные радикальной, жертвенной милостью."],[761,"r97dhn","Жгучий, пьянящий прилив праведного негодования; ощущение себя высшим судьёй Божьей справедливости."],[762,"cilgxe","Рана вдовы от тяжёлой утраты; возмущение как щит, чтобы не чувствовать горе под ним."],[763,"tjd4pb","Пьянящая власть вынести смертельный «праведный» приговор, который губит другого."],[764,"8gze79","Жар приливает к лицу, и сразу начинается навязчивая сборка «идеального, уничтожающего аргумента»."],[765,"14cp7sz","Трение с Левием (Священник): требует немедленной казни поверх бережного посредничества Левия."],[766,"1569vlp","Закрой ноутбук. Не публикуй критику. Помолись прямо о благословении и восстановлении того, кого собирался обличить."],[767,"1qgfpxm","Принять как реальность: «В гневе человек не делает угодного Богу». Жестокость никогда не оправдывается точностью."],[768,"k8545t","Полный пост от любых онлайн-споров о богословии, публичных разоблачений и обличений."],[769,"7fz4c5","Заменить алтарь ревности без поручения (который ведёт к резне) ревностью по поручению: действовать, только когда тебя полностью ограничивает радикальная милость."],[770,"56e997","Сыны грома"],[771,"mvrcr0","Лк. 9:54"],[772,"or3mk6","Апостолы"],[773,"r45hl5","Ближний круг"],[774,"1hp1e1m","Страстность"],[775,"16raehe","Преданность"],[776,"j9uidy","Смелость"],[777,"5m4wh9","Мстительность"],[778,"vh7noa","Безжалостность"],[779,"1lygja0","Горячность"],[780,"34bg97","Самарянское селение их отвергает. Они просят Иисуса свести огонь с неба, чтобы стереть селение с лица земли в «праведной ревности»."],[781,"kkixl2","Иисус упрекает их: «Вы не знаете, какого вы духа». Обуздать клинок. Поднимать ревность только по Божьему поручению, полностью ограниченную радикальной милостью."],[782,"112btb6","Резня в Сихеме"],[783,"1lnzedz","Быт. 34:25"],[784,"qolwav","Стражи"],[785,"isj9i","Защитники"],[786,"1r435yi","Защита"],[787,"1g4c6mu","Ревность"],[788,"mg053q","Жестокость"],[789,"952d0y","Коварство"],[790,"1jbne04","Мстительность"],[791,"18qj9xx","Глубокая праведная боль из-за бесчестья их сестры Дины. Религиозный завет (обрезание) становится оружием для совершенно несоразмерной резни целого города."],[792,"153e9uf","Иаков упрекает их за то, что они сделали его ненавистным для жителей той земли. Колено Симеона позже рассеяно: ревность без поручения разрушает собственное наследство."],[793,"lkje8h","Пётр с мечом"],[794,"hfbxrg","Ин. 18:10"],[795,"zblh8h","Апостол"],[796,"1jlhxb9","Камень"],[797,"1r435yi","Защита"],[798,"j9uidy","Смелость"],[799,"shoc3d","Преданность делу"],[800,"mdwqm2","Реактивность"],[801,"1iky40u","Плотское рвение"],[802,"c8zzvi","Возмущение"],[803,"16g4ui1","Во время ареста в саду полагается на плоть и ревность без поручения. Бьёт слугу первосвященника и отсекает ему ухо, чтобы защитить Царство голой силой."],[804,"18cao6a","Иисус резко останавливает его («Вложи меч в ножны!») и сам исправляет вред, исцеляя ухо врага: Его Царство воюет не так, как мир."],[805,"bu8kje","Щедрость ⇌ Дефицит"],[807,"1ejapx0","Щедрость"],[808,"n3hg1p","Жить из изобилия Царства. Умножение. (Притч. 11:24)"],[809,"pmk06r","Дефицит"],[810,"1s3hyez","Дух нехватки. Удерживать. У каждых отношений есть цена. (Агг. 1:6)"],[811,"1afn4e0","Завулон"],[812,"amo4do","Купец"],[814,"tc2hwv","«Завулон будет жить у морского побережья и будет гаванью для кораблей…» — Быт. 49:13"],[815,"mhjuko","Маммона"],[816,"1ejapx0","Щедрость"],[817,"1frqcff","Щедрость"],[818,"15xv123","Умножение"],[819,"19o1k7c","Находчивость"],[820,"4q6l2t","Стратег"],[821,"1dr934q","Жадность"],[822,"131qgsz","Накопительство"],[823,"d6fyf5","Трудоголизм"],[824,"hki80j","Умножение"],[825,"1ejapx0","Щедрость"],[826,"1ly225e","Масштабирование"],[827,"d1nqjf","Ряды Завулона в Секелаге"],[828,"6rfg0b","Елон Завулонянин"],[829,"16jlg70","Закхей"],[830,"o3rxtl","Матфей"],[831,"k5tvt0","Лидия"],[832,"bds25","Иосиф Аримафейский"],[833,"1vpqedx","Корнилий"],[834,"1gt3d6f","Богатый юноша"],[835,"7yqtvw","Анания и Сапфира"],[837,"55qoup","Гавань для кораблей: торговля как ворота для Евангелия. Опасность в том, что ворота превращаются в пункт сбора пошлины."],[838,"bb8zsy","В рабстве у бухгалтерии: запасы копятся на случай голода, которого Бог не посылал, у каждых отношений есть цена, святое продаётся."],[839,"2mmnxf","Бог касается житниц: квартал без роста, сорванная сделка, открытие, что манна портится, если её копить. Обеспечение заново учишься принимать каждый день."],[840,"1va9l0z","«Будет гаванью для кораблей»: богатство как гавань, а не крепость. Четырёхкратное возмещение Закхея питает то самое Царство, которое его освободило."],[841,"dnqvgq","Атака приходит, когда проседает показатель: выручка стоит на месте, случился непредвиденный расход. Паника дефицита бьёт ровно тогда, когда баланс меньше всего способен доказать твою ценность (Агг. 1:6)."],[842,"r448rf","Прорыв выглядит так: ты добровольно и болезненно отдаёшь именно в тот момент, когда страх велит копить, и ломаешь чары Маммоны, перещедрив её."],[843,"1ia8bne","Джордж Мюллер"],[844,"liiwl4","XIX в."],[845,"19q2rbo","Обеспечил кровом 10 000 сирот, ни разу не попросив денег у человека. Обеспечение через молитву: дух дефицита умер от голода на отвеченной вере."],[846,"1yguq9a","Р. Г. Летурно"],[847,"syhnso","XX в."],[848,"fdsvw8","Промышленник, строивший землеройную технику, перевернул десятину: жил на 10%, отдавал 90%. «Я отгребаю лопатой, а Бог подгребает обратно, только у Бога лопата больше»."],[849,"16gwys","Твоя ценность полностью привязана к состоянию, выручке или показателям продуктивности."],[850,"1jkq4o3","Трудно быть рядом с семьёй, когда бизнес стоит или падает."],[851,"15u04ox","Оправдываешь крайнее накопительство, переименовав его в «мудрое управление»."],[852,"1ffdwmw","Монетизируешь каждое хобби, отношения или святое место (благодать превращается в сделку)."],[853,"1ftoy2g","Тебе физически плохо или глубоко тревожно, когда приходится неожиданно тратить деньги."],[854,"ag5jc0","Отказываешься вкладываться в собственное эмоциональное и духовное исцеление, потому что это «слишком дорого»."],[855,"15yo00q","Открытые горизонты и что-то настоящее, что можно умножать."],[856,"vhen8d","Ваал / Маммона"],[857,"mkdph4","Превращает открытые ладони финансов Царства в духовную кабалу сделок, где даяние используют, чтобы управлять исходами."],[858,"shd3uy","Дающий"],[859,"zw8047","Сирота (ужас дефицита)"],[860,"1359q7c","Комфорт и контроль"],[861,"151wfsj","Ваал/Маммона"],[862,"1irlhzq","«Постоянный рост оправдывает моё полупослушание»."],[863,"1fsa3nf","<strong>Путь царя:</strong> сделать радикальную щедрость оружием активной духовной войны; полностью разрушить алтарь Маммоны, безоговорочно доверяя Божьему, а не рукотворному обеспечению."],[864,"xkd8qs","Выгорание от приобретения: отчаяние, когда стоящая на месте выручка или сорванная цель обесценивает всю идентичность."],[865,"sfb7mc","Изоляция сделок: огромная сеть контактов, но ни одного настоящего друга, потому что каждый воспринимается как рычаг."],[866,"j4hdzj","Накопительство сделок: монетизация каждых отношений, хобби и святого места; ненасытный аппетит к «большему». (1 Тим. 6:10)"],[867,"bags5a","Радикальная щедрость: открытые ладони, умножение Царства, которое просто питает жатву."],[868,"evxfet","Приглушённая паника о запасах, которая заставляет навязчиво считать, монетизировать и обеспечивать будущее."],[869,"hjhwp9","Сиротская рана дефицита; глубоко въевшийся ужас, что ресурсы кончатся и ты останешься ни с чем."],[870,"y8x5g8","Дофаминовый всплеск от «закрытой сделки» или растущего баланса, который на время глушит страх нехватки."],[871,"198wi19","Внезапно ухает в животе, когда клиент берёт паузу или показатель хоть день идёт вниз."],[872,"pcch6w","Трение с Неффалимом (Лань): его вольный дух без структуры кажется ленивым и убыточным."],[873,"kambxf","Сразу что-нибудь отдай. Разорви петлю дефицита: выпиши непрошеный чек или отдай какой-то ресурс бесплатно."],[874,"1hq37rw","Сменить убеждение «я кормилец» на «Бог мой источник, а я только проводник»."],[875,"1lctzfi","Автоматизировать щедрое даяние, чтобы оно происходило ощутимо, в первую очередь и с самого верха, не оставляя шанса придержать."],[876,"gtx8pw","Разрушить алтарь Маммоны (управление исходами через деньги) и поставить алтарь щедрости, направляя капитал только на умножение Царства."],[877,"kri711","Анания и Сапфира"],[878,"5cvsm7","Деян. 5:2"],[879,"12aogl7","Жертвователи"],[880,"16hqqjd","Члены церкви"],[881,"v2dbzg","Желание участвовать"],[882,"952d0y","Лживость"],[883,"131qgsz","Накопительство"],[884,"1cdxfuf","Тщеславие"],[885,"1uhrvcb","Хотят публичного престижа щедрости, втайне живя в ужасе дефицита. Лгут Святому Духу, чтобы оставить часть себе, делая вид, что отдают всё."],[886,"1cnkimi","Пётр обличает корневую ложь, и последствие мгновенно и смертельно. Остаётся грозным базовым предупреждением: нельзя позволять Маммоне захватить алтарь щедрости."],[887,"129dv0a","Богатый юноша"],[888,"15tmegg","Мк. 10:21"],[889,"9ek8kz","Управляющий"],[890,"1widmo4","Начальник"],[891,"rdavg4","Законопослушность"],[892,"ozaqdy","Ищет истину"],[893,"14vdvbu","Благоговение"],[894,"1dr934q","Жадность"],[895,"bncrku","Тяга к комфорту"],[896,"isu2z9","Идолопоклонство"],[897,"1b8pt06","Хочет вечной жизни, но полностью сросся со своим огромным имуществом. Безупречно соблюдает нравственный закон, но отказывается выпустить из рук свою бухгалтерию."],[898,"11m2ctb","Иисус любит его и говорит продать всё и раздать бедным. Он уходит опечаленным, выбрав алтарь Маммоны вместо приглашения следовать за Царём."],[899,"nihc4d","Мытарь Закхей"],[900,"1c4t4c6","Лк. 19:8"],[901,"344ycc","Начальник мытарей"],[902,"t8dq7p","Купец"],[903,"19o1k7c","Находчивость"],[904,"3h0w7p","Ищет Иисуса"],[905,"1l08ymx","Вымогательство"],[906,"1ctv0ex","Жадность"],[907,"1356gqm","Накопительство"],[908,"11fmpmd","Залезает на дерево, только чтобы увидеть Иисуса, плотно укутанный богатством, украденным у собственного народа, и полностью живущий в духе Маммоны."],[909,"13dvq1q","Иисус сам напрашивается к нему в гости. В ответ на благодать Закхей полностью разрушает свой алтарь: отдаёт половину имения бедным и возвращает вчетверо всем, кого обманул."],[910,"1kocrrh","Истина ⇌ Обман"],[912,"1leplb7","Истина и разум"],[913,"1xngiu0","Обновление ума, чтобы жить в согласии с небом. Мудрость, которая говорит. (Ин. 8:32)"],[914,"ksh5pd","Обман и религиозность"],[915,"5lbm3d","Правила вместо отношений. Цинизм. (2 Тим. 4:3)"],[916,"1cq7ixz","Левий"],[917,"cj1xv7","Священник"],[919,"u72660","«Твои Туммим и Урим принадлежат благочестивому Твоему…» — Втор. 33:8"],[920,"1y626di","Религиозность"],[921,"u5wm3h","Посредничество"],[922,"wpz0fy","Посвящённость"],[923,"1duxcym","Учительство"],[924,"14vdvbu","Благоговение"],[925,"1v7kcle","Охрана"],[926,"1hfbnop","Законничество"],[927,"1pegfct","Гордость"],[928,"1llx6b5","Осуждение"],[929,"10ehljv","Посвящение"],[930,"1duxcym","Учительство"],[931,"10fdwo4","Присутствие"],[932,"o8e9iy","Аарон"],[933,"8sbwb3","Ездра"],[934,"1m9t6sg","Священник Захария"],[935,"avb2s","Иоанн Креститель"],[936,"1jnbk7r","Илий"],[937,"hujea","Фарисеи"],[939,"16sszo5","Хранит доверенное и учит пути. Опасность в том, чтобы охранять Бога от людей, к которым Он тянется."],[940,"kko2rf","В рабстве у свода правил: правильные ответы вместо праведности, святость как дистанция, благодать как угроза, которой надо управлять."],[941,"1ckh0ti","Бог ломает систему, на которой держалась уверенность: миг Ихавода, умолкший голос. Пока отношения не построятся заново на присутствии, а не на точности."],[942,"1rh7g31","«Твои Туммим и Урим принадлежат благочестивому Твоему»: истина и присутствие снова вместе. Священник, который приводит сломленных людей к Богу, а не защищает Бога от сломленных людей."],[943,"2amfrq","Атака приходит, когда кто-то понимает благодать «неправильно»: неточное богословие, незаслуженная милость, неряшливое поклонение. Рефлекс поправить срабатывает раньше, чем успевает загрузиться сострадание (Лк. 15:28)."],[944,"1j67x6r","Прорыв выглядит так: ты спрашиваешь о сердце, прежде чем поправлять слова. Служишь там, где безупречное учение не спасёт момент, и обнаруживаешь, что Бог уже там."],[945,"1bcix8y","Мартин Лютер"],[946,"1t7s7b7","XVI в."],[947,"88dayr","Монах, щепетильный до отчаяния, часами исповедовался каждый день, пока слова «Праведный верой жив будет» не сломали машину религии и не основали её заново на благодати."],[948,"19oem3n","Граф Цинцендорф"],[949,"u4uh1x","XVIII в."],[950,"1ain5m6","Променял мёртвую ортодоксию на веру сердца («У меня одна страсть — это Он»): давал приют беженцам и начал столетнее молитвенное собрание, из которого родились современные миссии."],[951,"ncmx19","Духовная гордость и сознательная изоляция во имя «святости»."],[952,"1tz87wv","Судишь, как другие ходят с Богом, по своим личным, сверхконкретным убеждениям."],[953,"1b7agk0","Богословская точность и соблюдение правил важнее настоящей любви и плода."],[954,"1vr54dv","Чистая благодать кажется опасной, и ею надо управлять человеческими правилами."],[955,"1yntjqs","Поправляешь богословие или формулировки человека, пока он горюет."],[956,"wubt6s","Создаёшь бесконечные подпункты правил, чтобы управлять поведением других и контролировать его."],[957,"1uttkrf","Посвящение с настоящим поручением."],[958,"dmg2gr","Пифон / Фарисей"],[959,"18nj2kl","Обвивается вокруг призвания к истине и выдавливает из него дыхание, заменяя откровение интеллектуальным цинизмом."],[960,"7cu1px","Учитель"],[961,"6kymt5","Пришелец (разочарование)"],[962,"1qdhw5z","Контроль и одобрение"],[963,"huf81l","Пифон/Фарисей"],[964,"93ix4r","«Я должен стоять у ворот и следить за правилами, чтобы защитить Бога»."],[965,"o3d4i3","<strong>Путь пророка:</strong> перейти от охраны интеллектуальных данных и правил к живой, неидеальной вере, которую проживают; разрушить алтарь религиозности, чтобы по-настоящему передавать Божье присутствие."],[966,"1v10sob","Выгорание от перфекционизма: истощение от того, что ты надзираешь за поведением и богословием всех вокруг."],[967,"i9zgvz","Изоляция «башни из слоновой кости»: уход от неряшливых человеческих нужд в стерильную безопасность чистого богословия."],[968,"1anelvi","Привратничество: аппетит к интеллектуальному превосходству и к тому, чтобы доказывать неправоту других ради духовной безопасности. (Мф. 23:13)"],[969,"m5qf55","Посвящённое посредничество: мост между Богом и человеком из абсолютной истины и глубокого сострадания."],[970,"1atz11w","Холодное, самодовольное превосходство, за которым глубоко укоренившийся ужас оказаться «неправым» или испачкаться в неряшливых эмоциях."],[971,"stfxsd","Рана пришельца от разочарования: видел, как рушатся несовершенные системы, и ищет безопасности в безупречном, стерильном учении."],[972,"48c5yl","Самодовольная, приятная безопасность «богословской правоты» без настоящей уязвимости."],[973,"5l29m0","Внутренне передёргивает, и ум сразу ставит ярлык «ересь», когда кто-то неточно говорит о Боге."],[974,"1av03h","Трение с Гадом (Воитель): Гад нарушит правила, чтобы сделать дело, и это приводит Левия в ужас."],[975,"13xadva","Остановись. Не поправляй их богословие. Вместо этого задай вопрос об их сердце."],[976,"1vjw0tf","Принять правду, что богословие без любви бесовское, а перфекционизм всего лишь трусливый щит от близости."],[977,"12nump9","Обязательное погружение в неряшливое, ничем не регламентированное служение (например, помощь самым нуждающимся), где безупречное богословие не спасёт момент."],[978,"jl8xrc","Снести алтарь религиозности (надзор за правилами) и поставить алтарь посредничества (приводить сломленных людей к святому Богу)."],[979,"hujea","Фарисеи"],[980,"1ozfcel","Мф. 23:23"],[981,"1kgupsp","Стражи истины"],[982,"1vni60w","Набожность"],[983,"dqo041","Дисциплина"],[984,"1bb1n4a","Учёность"],[985,"7dzxb6","Законничество"],[986,"10hjj6","Лицемерие"],[987,"w8911s","Гордыня"],[988,"wpsqx8","Безупречно охраняют текст Закона и совершенно не замечают Слово, ставшее плотью. Насаждают строгие, удушающие правила, чтобы управлять Богом, и это заканчивается убийством Мессии."],[989,"ae8957","Иисус снова и снова нарушает их правила о субботе, чтобы исцелять людей: сострадание важнее кодекса. Переход от охраны интеллектуальных данных к живой, неидеальной вере."],[990,"s76fyb","Священник Илий"],[991,"1h43y1g","1 Цар. 3:13"],[992,"1qfxzdo","Первосвященник"],[993,"yn8nk4","Судья"],[994,"19v3dfg","Наставник"],[995,"vp7tiw","Доступность"],[996,"pq49ha","Пассивность"],[997,"15b7l5d","Компромисс"],[998,"1butnve","Страх"],[999,"12sl2v4","Занимает место духовной власти, но не находит мужества обличить грех внутри. Позволяет сыновьям оскорблять жертвоприношения из пассивного избегания и ради удобства."],[1000,"1m7y54r","Бог полностью обходит Илия и говорит с мальчиком Самуилом, объявляя суд дому Илия. Не смог развернуться: слава отошла (Ихавод), потому что священник не уберёг святое."],[1001,"1m9t6sg","Священник Захария"],[1002,"xegzno","Лк. 1:18"],[1003,"15j5cvu","Священник"],[1004,"9ss60z","Отец"],[1005,"1kxuxch","Праведность"],[1006,"fn07tp","Непорочность"],[1007,"1048362","Верность"],[1008,"1tkbjqg","Цинизм"],[1009,"9nadmd","Неверие"],[1010,"2e07yk","Негибкость"],[1011,"1n6zu1o","Встречает ангела в святилище, но пропускает откровение через логику и биологическую невозможность. Требует знака, потому что его богословская система не выдерживает чуда."],[1012,"1122w0u","Онемел до рождения и наречения ребёнка (Лк. 1:64) и был вынужден молча вынашивать чудо. Цинизм снят, и первые его слова после были чистой пророческой хвалой."],[1013,"dmedzl","Иссахар"],[1014,"i4h3j0","Мудрец"],[1016,"1f1p7ag","«…из рода Иссахара, людей разумных, которые знали, что и когда надлежало делать Израилю…» — 1 Пар. 12:32"],[1017,"i36sl5","Рассудок"],[1018,"668ma7","Мудрость в вере"],[1019,"mj15l5","Проницательность"],[1020,"161gbm5","Мудрость"],[1021,"139qcbt","Наблюдательность"],[1022,"1u6xvx","Понимание"],[1023,"lhavc7","Страх"],[1024,"1mqb2p","Пассивность"],[1025,"1i4dfhz","Перемудривание"],[1026,"w80lc6","Мудрость"],[1027,"b4hrdw","Предвидение"],[1028,"1h5l237","Различение"],[1029,"199c6lk","Сыны Иссахара"],[1030,"rjbw44","Никодим"],[1031,"11ftiq8","Соломон"],[1032,"ojaela","Волхвы"],[1033,"1duxxvn","Верийцы"],[1034,"1sfeoo0","Даниил (толкователь)"],[1035,"tzsmyb","Гедеон"],[1036,"1vgkjx1","Афиняне"],[1038,"vso4ll","Понимает времена и знает, что делать Израилю. Опасность в том, чтобы знать вечно и не делать никогда."],[1039,"lzgg87","В рабстве у уверенности: ещё одна книга, ещё один знак, ещё одна модель. Исследование как крепость против риска послушания."],[1040,"yls4hw","Бог убирает переменные: войско сокращено до 300, руно ответило и отставлено. Послушания требуют раньше, чем данные полны."],[1041,"1n0kbvl","«Людей разумных, которые знали, что и когда надлежало делать Израилю» (1 Пар. 12:32): различение, которое доходит до решения. Свиток наконец обменян на шаг."],[1042,"cuev71","Атака приходит в точке решения: в тот миг, когда анализ должен стать действием, страх шепчет «сначала ещё немного изучу» (Суд. 6:36–40)."],[1043,"6zuhso","Прорыв выглядит так: ты действуешь, имея 70% информации: отправляешь неидеальное, говоришь рискованное слово, и обнаруживаешь, что недостающей переменной было послушание."],[1044,"ato3db","Блез Паскаль"],[1045,"1lsd5j2","XVII в."],[1046,"1jixdpv","Величайший аналитический ум своего века встретил Бога в огне («ОГОНЬ… Бог Авраама… не философов») и зашил эту уверенность в подкладку своего камзола."],[1047,"4o8m19","К. С. Льюис"],[1048,"syhnso","XX в."],[1049,"1c9nkq4","По его собственным словам, «самый унылый и неохотный новообращённый во всей Англии». Дошёл анализом до самой двери, всё равно преклонил колени и остаток жизни посвятил доводам в пользу этого шага."],[1050,"8px33u","Тяжёлый аналитический паралич под маской «ожидания Господа»."],[1051,"2fv839","Бесконечно потребляешь богословие, подкасты и схемы, так и не начиная действовать."],[1052,"w99dst","Парализующий страх выглядеть глупо мешает заговорить в решающие моменты."],[1053,"8g4zhr","Уход в эзотерику, нью-эйдж или сверхсложные прогнозные модели, чтобы чувствовать себя в безопасности."],[1054,"qrny9o","Прочитал 50 книг на одну тему, но так и не сделал первого практического шага."],[1055,"kqq19x","Ждёшь от Бога «идеального знака» или совпадения обстоятельств, которое так и не приходит."],[1056,"neq2g8","Партнёрство с Богом в видении."],[1057,"1ahdwl9","Пифон / Трусость"],[1058,"1n5mp2c","Прикрывается «мудростью» и «ожиданием Господа», чтобы вызвать тяжёлый аналитический паралич и не дать послушаться."],[1059,"12foxhd","Пророк"],[1060,"v9hxsy","Пришелец (отчуждение)"],[1061,"10fbl8e","Контроль"],[1062,"zc94yb","Пифон/Трусость"],[1063,"1fyqnyp","«Я должен глубоко понять всё, прежде чем сделать шаг и послушаться»."],[1064,"14fkcjf","<strong>Путь пророка и священника:</strong> решительно перейти от бесконечного анализа и наблюдения к смелому действию; разрушить алтарь рассудка, говоря правду даже тогда, когда это кажется рискованным."],[1065,"15n7avx","Выгорание от аналитического паралича: умственное истощение от просчёта тысяч переменных без единого действия."],[1066,"deqvmm","Изоляция «наблюдателя»: смотреть игру с трибун и никогда не рисковать провалом на поле."],[1067,"105e2r0","Накопительство информации: бесконечное потребление подкастов, схем и данных, чтобы чувствовать себя готовым, под которым прячется глубокая трусость. (Екк. 12:12)"],[1068,"yuesh9","Смелое предвидение: глубоко понимать времена и решительно действовать по этой мудрости, не дожидаясь всех переменных."],[1069,"nbd74","Парализующий страх упустить переменную; бесконечная петля «а что если», которая ощущается как ответственная осторожность."],[1070,"v9vpyj","Рана пришельца от отчуждения: интеллект как защитный буфер от мира, который кажется хаотичным и неуправляемым."],[1071,"ibb0z5","Иллюзия прогресса от новой информации без риска действовать."],[1072,"14ucubr","Глубокий страх и фраза: «Мне просто нужно сначала ещё немного это изучить»."],[1073,"wiy5ye","Трение с Рувимом (Первенец): Иссахар в ужасе смотрит, как Рувим действует импульсивно, не думая."],[1074,"1qdmus6","Действуй немедленно. Отправь письмо с опечаткой. Запусти продукт недоделанным. Разорви петлю совершенства."],[1075,"mpoebh","Понять, что сбор данных сверх того, что нужно для действия, уже не мудрость, а активная трусость."],[1076,"1ovz8t4","Ввести жёсткие сроки на решения (например, не больше 48 часов на изучение), после которых действие обязательно, даже если данных не хватает."],[1077,"1r7394z","Разрушить алтарь рассудка (где безопасность ищут в логике) и построить алтарь мудрости в вере (где безопасность находят в послушании, несмотря на неизвестное)."],[1078,"8554r7","Никодим ночью"],[1079,"1bwmd9p","Ин. 3:2"],[1080,"123ron6","Учитель Израиля"],[1081,"mkaky5","Мудрец"],[1082,"u4m99m","Искатель"],[1083,"14vdvbu","Благоговение"],[1084,"1rwoz92","Трусость"],[1085,"efigbg","Забота о статусе"],[1086,"k84npz","Аналитичность"],[1087,"1w75mnx","Узнаёт истину Иисуса, но боится социальной и структурной цены близости к Нему. Ищет глубоких богословских ответов, но только под покровом темноты."],[1088,"10amgx7","Иисус ставит его перед необходимостью быть «заново рожденным»: полная перезагрузка системы. В конце концов Никодим выходит при свете дня, чтобы забрать тело Иисуса, и переходит от тайного анализа к преданности."],[1089,"1fz78pe","Афиняне"],[1090,"1bhrx17","Деян. 17:21"],[1091,"ug8apd","Мыслители"],[1092,"s3kx19","Философы"],[1093,"6gtirh","Любознательность"],[1094,"jnryzb","Интеллект"],[1095,"pq49ha","Пассивность"],[1096,"rxbd6x","Спорщики"],[1097,"vyewlj","Уклончивость"],[1098,"9rn5t3","Всё время проводят в том, чтобы говорить о новейших идеях и слушать о них. Бесконечное потребление философии, которое никогда не приходит к преображающей истине или действию."],[1099,"6na6wu","Павел провозглашает ясную, нефилософскую истину о воскресении. Решительный переход от бесконечного наблюдения к смелому, немедленному действию, несмотря на недостающие переменные."],[1100,"1cgyx7v","Руно Гедеона"],[1101,"1pxd26a","Суд. 6:36"],[1102,"yn8nk4","Судья"],[1103,"1nghopl","Избавитель"],[1104,"1utcrn2","Смирение"],[1105,"zunyrr","Осторожность"],[1106,"1butnve","Страх"],[1107,"1i4dfhz","Перемудривание"],[1108,"1qlp03f","Паралич"],[1109,"154wvp1","Прячется от врага в давильне. Требует знак за знаком (руно), чтобы просчитать каждую переменную, потому что до смерти боится выполнить повеление."],[1110,"1w30g6p","Бог терпеливо проводит его через данные, а затем заставляет сократить войско до 300 человек, убирая все логические преимущества и требуя слепого послушания."],[1111,"mucyq0","Дан"],[1112,"1atr7fn","Судья"],[1114,"l61tod","«Дан будет судить свой народ как один из родов Израиля». — Быт. 49:16"],[1115,"y0e9ow","Цинизм"],[1116,"4e4n21","Восстанавливающий суд"],[1117,"gxyx0a","Говорит правду"],[1118,"1w9hn5r","Справедливость"],[1119,"1r435yi","Защита"],[1120,"k84npz","Аналитичность"],[1121,"y0e9ow","Цинизм"],[1122,"1phe05k","Клевета"],[1123,"dlzif1","Разделение"],[1124,"ug0m62","Правдивость"],[1125,"ske8aq","Справедливость"],[1126,"1wyj3mi","Защита"],[1127,"8fhm4o","Самсон"],[1128,"zi6bc7","Колено Дана"],[1129,"i0hfsr","Нафан"],[1130,"4hnp0d","Фома"],[1131,"67h280","Мариам"],[1132,"1spw1db","Михей"],[1133,"1jfcqp1","Амос"],[1135,"1p28qdf","«Дан будет судить свой народ»: видит изъян, который никто больше не назовёт. Опасность в том, чтобы стать Обвинителем вместо защитника."],[1136,"18wli6u","В рабстве у приговора: цинизм как броня, критика как идентичность, связь с другими только через общее презрение."],[1137,"zhpogf","Бог заставляет тебя защищать то, что тебе хотелось бы препарировать: строить то, что ты критиковал, заступаться за лидера, которого ты разоблачил, семь дней вне стана."],[1138,"aiaurc","Путь Нафана: изъян назван наедине, внутри завета, через притчу, которая спасает царя, а не через приговор, который его губит. Суд, который восстанавливает."],[1139,"1due4vm","Атака приходит, когда у лидера или системы обнаруживается настоящий изъян: точное наблюдение приходит вместе с ядовитым духом, и точность делает яд похожим на праведность (Чис. 12:1)."],[1140,"pmewt5","Прорыв выглядит так: правило строителя (на каждую критику столько же часов созидания) и умение публично порадоваться чужой победе, прежде чем разбирать её наедине."],[1141,"2hcpke","Малкольм Маггеридж"],[1142,"syhnso","XX в."],[1143,"17j2tic","Самый острый профессиональный циник Британии десятилетиями разбирал всё до основания, а потом встретил Иисуса через служение Матери Терезы, и скальпель превратился в «Нечто прекрасное для Бога»."],[1144,"1dup8w8","Г. К. Честертон"],[1145,"syhnso","XX в."],[1146,"1honzrk","Спорил со всеми и зарабатывал тем, что разносил плохие идеи, но оружием у него была радость, и каждого оппонента он сохранял другом. Критика без презрения."],[1147,"kjpfe8","Сближаешься с людьми только через общий цинизм и общую ненависть."],[1148,"uge0nm","Придираешься к проповеди и критикуешь её вместо того, чтобы по-настоящему поклоняться или принимать."],[1149,"1vkllre","Различение как оружие, чтобы разрушать, а не щит, чтобы защищать."],[1150,"iwy12p","Уверен, что у каждого, кто с тобой не согласен, тёмный скрытый мотив."],[1151,"1s2bbcg","Строишь всю свою площадку или личность на критике других служений и людей."],[1152,"rn5cpm","Тебе физически трудно порадоваться чужому прорыву или успеху."],[1153,"qlotqy","Суд, который выносят в заветной общине, а не в одиночку."],[1154,"ry9kkc","Пифон / Обвинитель"],[1155,"d4df84","Подаёт формально точные факты с совершенно ядовитым духом, чтобы душить и разрушать. Писание прямо называет источник этого шаблона: «Обвинитель наших братьев, обвинявший их день и ночь перед Богом» (Откр. 12:10). Признак не в неточности, а в том, что приговор никогда не нацелен на восстановление. Призвание Дана судить; подделка обвиняет."],[1156,"12foxhd","Пророк"],[1157,"1fe1zv1","Пришелец (бессилие)"],[1158,"10fbl8e","Контроль"],[1159,"dhdkz2","Пифон/Обвинитель"],[1160,"1akf05g","«Верный приговор остаётся праведным, с каким бы духом его ни вынесли»."],[1161,"5cxp54","<strong>Путь пророка и священника:</strong> восстанавливать сломанные системы любовью и восстанавливающим судом, а не ядовитой критикой; сознательно разрушать алтарь цинизма, ища в других их искупительный потенциал."],[1162,"1ecb3iy","Выгорание от цинизма: глубокое разъедающее гниение души от уверенности, что у каждого тёмный скрытый мотив."],[1163,"1s0y9f6","Изоляция эхо-камеры: связь только с теми, с кем общая ненависть и общая критика."],[1164,"1afm6xd","Деконструкция: ненасытный аппетит сносить системы, лидеров и идеи, ничего не строя. (Притч. 16:28)"],[1165,"1e0cqoe","Восстанавливающая справедливость: находить структурные изъяны только ради того, чтобы исцелять и защищать общину."],[1166,"1sit1u5","Тёмный, изолирующий азарт цинизма; отстранённая, насмешливая поза, которая ждёт худшего от всех лидеров и систем."],[1167,"1997nc1","Рана пришельца от бессилия: критика как оружие, чтобы чувствовать контроль, когда нет структурной власти."],[1168,"1dgrqqj","Тёмный азарт найти изъян, доказать неправоту лидера и защитить себя от обмана."],[1169,"c2vt82","Телесная усмешка и чувство превосходства, когда слушаешь чужое видение или презентацию."],[1170,"m613gr","Трение с Иудой (Лев): постоянно указывает на изъяны в огромных, оптимистичных замыслах Иуды."],[1171,"ptjy3g","Не произноси критику вслух. Заставь себя найти и назвать одну по-настоящему блестящую вещь в этой системе."],[1172,"1t36pas","Понять, что критика без готовности строить по сути колдовство, а точность не оправдывает ядовитый дух."],[1173,"1iy9b3q","Ввести «правило строителя»: на каждую критику в адрес системы ты обязан потратить столько же часов на создание решения."],[1174,"7y6olo","Заменить алтарь цинизма (разрушение) алтарём восстанавливающего суда (находить изъян только ради исцеления тела)."],[1175,"1io71ef","Самсон, судья из колена Дана"],[1176,"okxh0g","Суд. 16:28"],[1177,"x4lexz","Судья Израиля"],[1178,"mr7crb","Назорей"],[1179,"1nghopl","Избавитель"],[1180,"r5dtlh","Помазание"],[1181,"yvk4wa","Бесстрашие"],[1182,"1y17w9g","Призван от утробы"],[1183,"86remq","Непокорность"],[1184,"1ck9ag2","Изоляция"],[1185,"1jk6mle","Месть"],[1186,"1wxz8k1","Единственный судья Израиля, который так и не собрал войска. Судейское помазание Дана, прожитое полностью в одиночку: двадцать лет личной вражды и личной мести, ни разу не подчинив свой суд заветной общине и не позвав колена на войну. Сила была настоящей; подотчётности не было никогда."],[1187,"1o6lu8i","Слепой, в оковах, вращая жернов у врагов, он впервые в повествовании молится: «Владыка Господи, вспомни меня». Суд, который он всегда вершил сам, наконец не захвачен, а испрошен, и избавление, которого он не добился за двадцать лет одиночных набегов, приходит в одно мгновение покорности."],[1188,"a6ob6f","Самочинное священство"],[1189,"r6613j","Суд. 18:30"],[1190,"1atr7fn","Судья"],[1191,"1wkdeay","Яростные защитники"],[1192,"3sm2ze","Сила"],[1193,"dv3t03","Хитрость"],[1194,"isu2z9","Идолопоклонство"],[1195,"lx07bh","Самочинность"],[1196,"18pqqcm","Раскол"],[1197,"hfbgkt","Отказываются сражаться за отведённый им удел и выбирают путь полегче. Ставят собственных идолов и самочинное, никому не подотчётное священство на севере."],[1198,"69l8m3","В конце концов земля уходит в плен: неподотчётный суд ведёт к изгнанию. Подчинить различение заветной общине, а не действовать как одинокий, циничный критик."],[1199,"4x7sol","Клевета Мариам"],[1200,"wvw5gh","Чис. 12:1"],[1201,"146nd0a","Пророчица"],[1202,"1widmo4","Лидер"],[1203,"1nmvlm","Поклоняющаяся"],[1204,"192rtr5","Бдительность"],[1205,"1r435yi","Защита"],[1206,"11om8bs","Критичность"],[1207,"1o6ha1y","Ревность"],[1208,"b9wxvd","Клевета"],[1209,"1basiar","Использует формально точный факт (Моисей женился на кушитке) как прикрытие для ядовитой, циничной атаки на его высшую власть и требует равенства."],[1210,"1b549s6","Поражена проказой и на 7 дней изгнана из стана. Восстановлена только потому, что тот самый лидер, которого она обвиняла (Моисей), смиренно заступился за её исцеление."]];
